class GuiOutputProxy:
    def __init__(self, output_queue, scoreboard_queue, original_stdout, section_queue=None):
        self.output_queue = output_queue
        self.scoreboard_queue = scoreboard_queue
        self.section_queue = section_queue
        self.original_stdout = original_stdout
        self.buffer = ""
        self.full_output = []
        self.scoreboard_pattern = re.compile(r"^(.+?) \| ([0-9]+:[0-9]{2}) \| (.+?): (\d+)\s+(.+?): (\d+)$")
        self.hide_gui_log_section = False

    def write(self, text):
        if not text:
            return
        self.full_output.append(text)
        _REAL_SLEEP(0.001)
        self.buffer += text
        while "\n" in self.buffer:
            line, self.buffer = self.buffer.split("\n", 1)
            clean = line.strip()
            self._maybe_scoreboard(clean)
            self._maybe_series_record(clean)
            if self._should_show_in_play_log(clean):
                self.output_queue.put(line + "\n")

    def flush(self):
        return

    def _maybe_scoreboard(self, line: str):
        match = self.scoreboard_pattern.match(line)
        if not match:
            return
        period, clock, team_a, score_a, team_b, score_b = match.groups()
        self.scoreboard_queue.put({
            "period": period,
            "clock": clock,
            "team_a": team_a,
            "score_a": score_a,
            "team_b": team_b,
            "score_b": score_b,
        })

    def _maybe_series_record(self, line: str):
        game_result = re.match(r"(.+?) win Game (\d+)\.", line)
        if game_result:
            winner, game_num = game_result.groups()
            self.scoreboard_queue.put({"game_result": f"G{game_num}: {winner} win"})
            return

        record_line = None
        label = "Series"
        if line.startswith("Series now:"):
            record_line = line[len("Series now:"):].strip()
            label = "Series now"
        elif line.startswith("Series:"):
            record_line = line[len("Series:"):].strip()
        elif line.startswith("SERIES FINAL"):
            self.scoreboard_queue.put({"series_status": line})
            return

        if record_line is None:
            return

        match = re.match(r"(.+?)\s+(\d+)\s+-\s+(\d+)\s+(.+)$", record_line)
        if not match:
            self.scoreboard_queue.put({"series_status": line})
            return

        team_a, wins_a, wins_b, team_b = match.groups()
        self.scoreboard_queue.put({
            "series_status": f"{label}: {team_a} {wins_a} - {wins_b} {team_b}",
            "series_team_a": team_a,
            "series_wins_a": wins_a,
            "series_team_b": team_b,
            "series_wins_b": wins_b,
        })

    def _should_show_in_play_log(self, line: str) -> bool:
        if not line:
            return True
        hidden_starts = (
            "SERIES GAME BOX SCORES", "SERIES AVERAGES", "SERIES 4TH QUARTER",
            "SERIES ADVANCED STATS", "SERIES SHOT DIET", "SERIES DEFENSIVE",
            "SERIES AWARDS", "FINAL BOX SCORE", "HALFTIME BOX SCORE",
            "END OF 1ST QUARTER BOX SCORE", "END OF 3RD QUARTER BOX SCORE",
            "END OF REGULATION BOX SCORE", "LIVE BOX SCORE", "GAME RECAP",
            "QUARTER BOX SCORE", "PLAYER QUARTER", "ADVANCED STATS",
            "SHOT DIET BOX SCORE", "DEFENSIVE CONTEST",
        )
        if any(line.startswith(prefix) for prefix in hidden_starts):
            self.hide_gui_log_section = True
            return False
        if self.hide_gui_log_section:
            if self.scoreboard_pattern.match(line) or "brings the ball up" in line or "Opening tip" in line or line.startswith("--- Start of"):
                self.hide_gui_log_section = False
            else:
                return False
        hidden_contains = (
            "BOX SCORE", "TEAM TOTALS", "Scouting report for", "Series adjustment:",
            "SERIES FINAL", "Player of the game:", "Top scorers:", "Biggest run:",
            "Turning point:", "Team extras:", "Defensive matchups to start",
            "PLAYER AVERAGES", "TEAM AVERAGES", "FGM/FGA", "3PM/3PA",
            "True shooting", "Shot Diet", "Shots Defended",
        )
        return not any(token in line for token in hidden_contains)

    def publish_series_sections(self):
        if self.section_queue is None:
            return
        text = "".join(self.full_output)
        sections = split_gui_series_sections(text)
        self.section_queue.put(sections)

