    def team_initials(team_name: str) -> str:
        words = [w for w in re.sub(r"[^A-Za-z0-9 ]", " ", team_name).split() if not w.isdigit()]
        if not words:
            return "TM"
        if len(words) == 1:
            return words[0][:3].upper()
        return "".join(w[0] for w in words[-2:]).upper()[:3]

    def team_logo_colors(team_name: str) -> Tuple[str, str]:
        palette = [
            ("#2563eb", "#eff6ff"), ("#dc2626", "#fff1f2"), ("#16a34a", "#f0fdf4"),
            ("#9333ea", "#faf5ff"), ("#ea580c", "#fff7ed"), ("#0891b2", "#ecfeff"),
            ("#ca8a04", "#fefce8"), ("#be123c", "#fff1f2"), ("#4338ca", "#eef2ff"),
            ("#0f766e", "#f0fdfa"),
        ]
        return palette[sum(ord(ch) for ch in team_name) % len(palette)]

    def olympic_flag_code(team_name: str) -> str | None:
        lower = team_name.lower()
        mapping = {
            "1992 usa dream team": "us",
            "dream team": "us",
            "2008 usa redeem team": "us",
            "redeem team": "us",
            "2024 olympic usa": "us",
            "2024 olympic canada": "ca",
            "2024 olympic australia": "au",
            "2024 olympic serbia": "rs",
            "2024 olympic france": "fr",
            "2024 olympic germany": "de",
            "2024 olympic greece": "gr",
            "2024 olympic spain": "es",
            "2024 olympic brazil": "br",
            "2024 olympic japan": "jp",
            "2024 olympic south sudan": "ss",
            "2024 olympic puerto rico": "pr",
        }
        for needle, code in mapping.items():
            if needle in lower:
                return code
        return None

