            ("pelicans", "no"), ("knicks", "ny"), ("thunder", "okc"), ("magic", "orl"),
            ("sixers", "phi"), ("76ers", "phi"), ("suns", "phx"), ("blazers", "por"),
            ("trail blazers", "por"), ("kings", "sac"), ("spurs", "sa"), ("raptors", "tor"),
