    def load_team_logo(team_name: str):
        flag_code = olympic_flag_code(team_name)
        if flag_code:
            cache_key = f"flag_{flag_code}_104"
            if cache_key in logo_images:
                return logo_images[cache_key]
            os.makedirs(logo_cache_dir, exist_ok=True)
            path = os.path.join(logo_cache_dir, f"{cache_key}.png")
            if not os.path.exists(path):
                url = f"https://flagcdn.com/w320/{flag_code}.png"
                try:
                    urllib.request.urlretrieve(url, path)
                except Exception:
                    return None
            try:
                image = tk.PhotoImage(file=path)
                if image.width() > 108 or image.height() > 108:
                    factor = max(1, int(max(image.width(), image.height()) / 100))
                    image = image.subsample(factor, factor)
                logo_images[cache_key] = image
                return image
            except Exception:
                return None

        code = franchise_logo_code(team_name)
        if not code:
            return None
        cache_key = f"team_{code}_104"
        if cache_key in logo_images:
            return logo_images[cache_key]
        os.makedirs(logo_cache_dir, exist_ok=True)
        path = os.path.join(logo_cache_dir, f"{code}.png")
        if not os.path.exists(path):
            url = f"https://a.espncdn.com/i/teamlogos/nba/500/{code}.png"
            try:
                urllib.request.urlretrieve(url, path)
            except Exception:
                return None
        try:
            image = tk.PhotoImage(file=path)
            if image.width() > 108 or image.height() > 108:
                factor = max(1, int(max(image.width(), image.height()) / 100))
                image = image.subsample(factor, factor)
            logo_images[cache_key] = image
            return image
        except Exception:
            return None

    def draw_country_flag(canvas, code: str, x0: float, y0: float, x1: float, y1: float):
        canvas.create_rectangle(x0, y0, x1, y1, fill="#f8fafc", outline="#f8fafc", width=2)
        w = x1 - x0
        h = y1 - y0
        def rect(rx0, ry0, rx1, ry1, color):
            canvas.create_rectangle(x0 + w * rx0, y0 + h * ry0, x0 + w * rx1, y0 + h * ry1, fill=color, outline=color)
        def poly(points, color):
            canvas.create_polygon([(x0 + w * px, y0 + h * py) for px, py in points], fill=color, outline=color)
        if code == "us":
            for i in range(13):
                rect(0, i / 13, 1, (i + 1) / 13, "#b91c1c" if i % 2 == 0 else "#f8fafc")
            rect(0, 0, 0.45, 7 / 13, "#1e3a8a")
            canvas.create_text(x0 + w * 0.225, y0 + h * 0.27, text="USA", fill="#f8fafc", font=("Segoe UI", max(8, int(h * 0.22)), "bold"))
        elif code == "ca":
            rect(0, 0, 0.25, 1, "#dc2626"); rect(0.75, 0, 1, 1, "#dc2626")
            poly([(0.50,0.20),(0.56,0.42),(0.68,0.36),(0.60,0.50),(0.70,0.60),(0.55,0.60),(0.50,0.80),(0.45,0.60),(0.30,0.60),(0.40,0.50),(0.32,0.36),(0.44,0.42)], "#dc2626")
        elif code == "au":
            rect(0, 0, 1, 1, "#1e3a8a"); canvas.create_text(x0 + w * 0.52, y0 + h * 0.53, text="★", fill="#f8fafc", font=("Segoe UI", max(9, int(h * 0.42)), "bold")); rect(0, 0, 0.45, 0.48, "#0f172a"); canvas.create_text(x0 + w * 0.225, y0 + h * 0.24, text="UK", fill="#f8fafc", font=("Segoe UI", max(7, int(h * 0.18)), "bold"))
        elif code == "rs":
            rect(0, 0, 1, 1/3, "#dc2626"); rect(0, 1/3, 1, 2/3, "#1d4ed8"); rect(0, 2/3, 1, 1, "#f8fafc")
        elif code == "fr":
            rect(0, 0, 1/3, 1, "#1d4ed8"); rect(1/3, 0, 2/3, 1, "#f8fafc"); rect(2/3, 0, 1, 1, "#dc2626")
        elif code == "de":
            rect(0, 0, 1, 1/3, "#111827"); rect(0, 1/3, 1, 2/3, "#dc2626"); rect(0, 2/3, 1, 1, "#facc15")
        elif code == "gr":
            for i in range(9):
                rect(0, i/9, 1, (i+1)/9, "#2563eb" if i % 2 == 0 else "#f8fafc")
            rect(0, 0, 0.42, 5/9, "#2563eb"); rect(0.17, 0, 0.25, 5/9, "#f8fafc"); rect(0, 2/9, 0.42, 3/9, "#f8fafc")
        elif code == "es":
            rect(0, 0, 1, 0.25, "#dc2626"); rect(0, 0.25, 1, 0.75, "#facc15"); rect(0, 0.75, 1, 1, "#dc2626")
        elif code == "br":
            rect(0, 0, 1, 1, "#16a34a"); poly([(0.50,0.12),(0.88,0.50),(0.50,0.88),(0.12,0.50)], "#facc15"); canvas.create_oval(x0+w*0.36, y0+h*0.28, x0+w*0.64, y0+h*0.72, fill="#1d4ed8", outline="#1d4ed8")
        elif code == "jp":
            rect(0, 0, 1, 1, "#f8fafc"); canvas.create_oval(x0+w*0.35, y0+h*0.22, x0+w*0.65, y0+h*0.78, fill="#dc2626", outline="#dc2626")
        elif code == "ss":
            rect(0, 0, 1, 1/3, "#111827"); rect(0, 1/3, 1, 2/3, "#dc2626"); rect(0, 2/3, 1, 1, "#16a34a"); poly([(0,0),(0.42,0.5),(0,1)], "#1d4ed8"); canvas.create_text(x0+w*0.14, y0+h*0.50, text="★", fill="#facc15", font=("Segoe UI", max(8, int(h * 0.28)), "bold"))
        elif code == "pr":
            for i in range(5):
                rect(0, i/5, 1, (i+1)/5, "#dc2626" if i % 2 == 0 else "#f8fafc")
            poly([(0,0),(0.46,0.5),(0,1)], "#1d4ed8"); canvas.create_text(x0+w*0.16, y0+h*0.50, text="★", fill="#f8fafc", font=("Segoe UI", max(8, int(h * 0.28)), "bold"))
        else:
            rect(0, 0, 1, 1, "#334155")

