    def player_initials(name: str) -> str:
        parts = [p for p in re.sub(r"[^A-Za-z0-9 ]", " ", name).split() if p]
        if not parts:
            return "?"
        return "".join(part[0] for part in parts[:2]).upper()

    HEADSHOT_CANVAS_SIZE = 82
    HEADSHOT_IMAGE_SIZE = (76, 76)
    HEADSHOT_CENTER = HEADSHOT_CANVAS_SIZE // 2

    def load_headshot_by_name(player_name: str):
        override_url = PLAYER_HEADSHOT_URLS.get(player_name)
        if override_url:
            cache_key = f"url:{player_name}"
            if cache_key in headshot_images:
                return headshot_images[cache_key]
            os.makedirs(headshot_cache_dir, exist_ok=True)
            safe_name = re.sub(r"[^A-Za-z0-9]+", "_", player_name).strip("_").lower()
            path = os.path.join(headshot_cache_dir, f"{safe_name}_override.png")
            if not os.path.exists(path):
                try:
                    urllib.request.urlretrieve(override_url, path)
                except Exception:
                    return None
            try:
                if Image is not None and ImageTk is not None:
                    pil_image = Image.open(path).convert("RGBA")
                    resample_filter = getattr(getattr(Image, "Resampling", Image), "LANCZOS", 1)
                    pil_image.thumbnail(HEADSHOT_IMAGE_SIZE, resample_filter)
                    image = ImageTk.PhotoImage(pil_image)
                else:
                    image = tk.PhotoImage(file=path)
                    if image.width() > HEADSHOT_IMAGE_SIZE[0] or image.height() > HEADSHOT_IMAGE_SIZE[1]:
                        factor = max(1, int(max(image.width() / HEADSHOT_IMAGE_SIZE[0], image.height() / HEADSHOT_IMAGE_SIZE[1])))
                        image = image.subsample(factor, factor)
                headshot_images[cache_key] = image
                return image
            except Exception:
                return None

        safe_name = re.sub(r"[^A-Za-z0-9]+", "_", player_name).strip("_").lower()
        espn_path = os.path.join(headshot_cache_dir, f"{safe_name}_espn.png")

        def find_espn_image(value):
            if isinstance(value, dict):
                href = value.get("href")
                if isinstance(href, str) and "espncdn.com" in href and ("headshot" in href or "players" in href):
                    return href
                for child in value.values():
                    found = find_espn_image(child)
                    if found:
                        return found
            elif isinstance(value, list):
                for child in value:
                    found = find_espn_image(child)
                    if found:
                        return found
            return None

        def download_espn_headshot():
            try:
                query = urllib.parse.quote(player_name)
                search_url = f"https://site.api.espn.com/apis/common/v3/search?query={query}&limit=8"
                request = urllib.request.Request(search_url, headers={"User-Agent": "Mozilla/5.0"})
                with urllib.request.urlopen(request, timeout=8) as response:
                    image_url = find_espn_image(json.load(response))
                if not image_url:
                    return
                image_request = urllib.request.Request(image_url, headers={"User-Agent": "Mozilla/5.0"})
                with urllib.request.urlopen(image_request, timeout=10) as response, open(espn_path, "wb") as output:
                    output.write(response.read())
                root.after(0, update_player_card_widget)
            except Exception:
                pass
            finally:
                headshot_downloads.discard(player_name)

        if not os.path.exists(espn_path) and player_name and player_name not in headshot_downloads:
            headshot_downloads.add(player_name)
            threading.Thread(target=download_espn_headshot, daemon=True).start()

        if os.path.exists(espn_path):
            cache_key = f"espn:{player_name}"
            if cache_key in headshot_images:
                return headshot_images[cache_key]
            try:
                if Image is not None and ImageTk is not None:
                    pil_image = Image.open(espn_path).convert("RGBA")
                    resample_filter = getattr(getattr(Image, "Resampling", Image), "LANCZOS", 1)
                    pil_image.thumbnail(HEADSHOT_IMAGE_SIZE, resample_filter)
                    image = ImageTk.PhotoImage(pil_image)
                else:
                    image = tk.PhotoImage(file=espn_path)
                headshot_images[cache_key] = image
                return image
            except Exception:
                pass

        player_id = PLAYER_HEADSHOT_IDS.get(player_name)
        if not player_id:
            return None
        if player_id in headshot_images:
            return headshot_images[player_id]
        os.makedirs(headshot_cache_dir, exist_ok=True)
        path = os.path.join(headshot_cache_dir, f"{player_id}.png")
        if not os.path.exists(path):
            url = f"https://cdn.nba.com/headshots/nba/latest/1040x760/{player_id}.png"
            try:
                urllib.request.urlretrieve(url, path)
            except Exception:
                return None
        try:
            if Image is not None and ImageTk is not None:
                pil_image = Image.open(path).convert("RGBA")
                resample_filter = getattr(getattr(Image, "Resampling", Image), "LANCZOS", 1)
                pil_image.thumbnail(HEADSHOT_IMAGE_SIZE, resample_filter)
                image = ImageTk.PhotoImage(pil_image)
            else:
                image = tk.PhotoImage(file=path)
                if image.width() > HEADSHOT_IMAGE_SIZE[0] or image.height() > HEADSHOT_IMAGE_SIZE[1]:
                    factor = max(1, int(max(image.width() / HEADSHOT_IMAGE_SIZE[0], image.height() / HEADSHOT_IMAGE_SIZE[1])))
                    image = image.subsample(factor, factor)
            headshot_images[player_id] = image
            return image
        except Exception:
            return None

    def load_player_headshot(player: Player):
        return load_headshot_by_name(player.name)

    def draw_player_headshot(canvas, player: Player | None):
        canvas.delete("all")
        if player is None:
            canvas.create_oval(6, 6, HEADSHOT_CANVAS_SIZE - 6, HEADSHOT_CANVAS_SIZE - 6, fill="#1f2937", outline="#64748b", width=2)
            canvas.create_oval(30, 15, 52, 39, fill="#9ca3af", outline="")
            canvas.create_oval(17, 42, 65, 86, fill="#6b7280", outline="")
            return
        image = load_player_headshot(player)
        if image is not None:
            canvas.create_image(HEADSHOT_CENTER, HEADSHOT_CENTER, image=image)
            canvas.image = image
            return
        canvas.create_oval(6, 6, HEADSHOT_CANVAS_SIZE - 6, HEADSHOT_CANVAS_SIZE - 6, fill="#1f2937", outline="#94a3b8", width=2)
        canvas.create_oval(30, 15, 52, 39, fill="#cbd5e1", outline="")
        canvas.create_oval(17, 42, 65, 86, fill="#64748b", outline="")
        canvas.create_text(HEADSHOT_CENTER, HEADSHOT_CANVAS_SIZE - 14, text=player_initials(player.name), fill="#f8fafc", font=("Segoe UI", 10, "bold"))

    def draw_named_headshot(canvas, player_name: str):
        canvas.delete("all")
        image = load_headshot_by_name(player_name)
        if image is not None:
            canvas.create_image(HEADSHOT_CENTER, HEADSHOT_CENTER, image=image)
            canvas.image = image
            return
        fill, text_color = team_logo_colors(player_name)
        canvas.create_oval(6, 6, HEADSHOT_CANVAS_SIZE - 6, HEADSHOT_CANVAS_SIZE - 6, fill=fill, outline="#f8fafc", width=2)
        canvas.create_text(HEADSHOT_CENTER, HEADSHOT_CENTER, text=player_initials(player_name), fill=text_color, font=("Segoe UI", 15, "bold"))

