    def is_made_basket_line(line: str) -> bool:
        lower = line.lower()
        if not line or any(bad in lower for bad in (
            "misses", "missed", "free throw", "foul on", "foul in", "offensive foul",
            "blocking foul", "loose-ball", "rebound", "turnover", "violation",
            "blocked", "swats", "rejects", "won't count"
        )):
            return False
        basket_phrases = (
            "knocks it down",
            "knocks down",
            "knocks it in",
            "drills",
            "buries it",
            "cash from",
            "splashes",
            "makes them pay",
            "is money",
            "gets to his spot and hits",
            "has the touch",
            "gets it to go",
            "muscles that one home",
            "finds enough daylight",
            "scores through",
            "converts the inbound set",
            "finishes the fastbreak",
            "finishes inside",
            "finishes through contact",
            "throws down",
            "hammers it home",
            "crushes it",
            "detonates",
            "poster",
            "rises up and",
            "slams home",
            "slams it home",
            "lays in",
            "second-chance bucket",
            "transition three",
            "putback in transition",
            "putback after the offensive board",
            "half-court heave at the buzzer",
            "and one!",
        )
        return any(phrase in lower for phrase in basket_phrases)

    last_basket_ft_state = {"player": None, "made": 0, "attempts": 0, "expected": 0}

    def last_basket_player_names() -> List[str]:
        names = []
        for team in (SIM_CONTEXT.get("teamA"), SIM_CONTEXT.get("teamB")):
            if team is not None:
                names.extend(p.name for p in team.roster)
        return sorted(set(names), key=len, reverse=True)

    def player_name_from_line(line: str) -> str | None:
        for name in last_basket_player_names():
            if line.startswith(name) or f" {name} " in f" {line} ":
                return name
        match = re.match(r"([A-Z][A-Za-z.'-]+(?: [A-Z][A-Za-z.'-]+){0,2}) ", line)
        return match.group(1) if match else None

    def maybe_start_free_throw_trip(line: str):
        lower = line.lower()
        expected = None
        player = None
        match = re.search(r"(.+?) (?:steps to the line for|will shoot) (\d+)", line, re.IGNORECASE)
        if match:
            player = player_name_from_line(match.group(1).strip()) or match.group(1).strip()
            expected = int(match.group(2))
        else:
            one_match = re.search(r"([A-Z][A-Za-z.'-]+(?: [A-Z][A-Za-z.'-]+){0,2}) gets one free throw", line)
            if one_match:
                player = player_name_from_line(one_match.group(1).strip()) or one_match.group(1).strip()
                expected = 1
        if expected and player:
            last_basket_ft_state.update({"player": player, "made": 0, "attempts": 0, "expected": expected})
            return True
        if "free throw" not in lower or "technical" in lower or "flagrant" in lower or "clear-path" in lower or "take-foul" in lower:
            return False
        return False

    def maybe_update_free_throw_summary(line: str) -> bool:
        lower = line.lower()
        active_trip = bool(last_basket_ft_state.get("player"))
        if "free throw" not in lower and not ("line" in lower and active_trip):
            return False
        made = any(phrase in lower for phrase in ("knocks down", "makes", "hits", "drops", "is good at the line"))
        missed = any(phrase in lower for phrase in ("misses", "leaves", "short", "cannot cash"))
        if not (made or missed):
            return maybe_start_free_throw_trip(line)

        player = last_basket_ft_state.get("player") or player_name_from_line(line)
        if not player:
            return False
        if last_basket_ft_state.get("player") != player:
            last_basket_ft_state.update({"player": player, "made": 0, "attempts": 0, "expected": 1})

        last_basket_ft_state["attempts"] += 1
        if made:
            last_basket_ft_state["made"] += 1
        expected = max(last_basket_ft_state["expected"], last_basket_ft_state["attempts"])
        last_basket_ft_state["expected"] = expected
        last_basket_var.set(f"{player} went {last_basket_ft_state['made']}/{expected} from the line.")
        if last_basket_ft_state["attempts"] >= expected:
            last_basket_ft_state.update({"player": None, "made": 0, "attempts": 0, "expected": 0})
        return True

    def made_basket_summary(line: str) -> str | None:
        player = player_name_from_line(line)
        if not player:
            return None
        lower = line.lower()
        is_three = any(word in lower for word in (
            "three", "3pt", "3-point", "from deep", "downtown", "behind the arc",
            "logo", "half-court", "transition three"
        ))
        points = 3 if is_three else 2
        return f"{player} scored a {points} pointer."

    def player_names_in_line(line: str) -> List[str]:
        padded = f" {line} "
        found = []
        for name in last_basket_player_names():
            if line.startswith(name):
                found.append((0, name))
                continue
            idx = padded.find(f" {name} ")
            if idx >= 0:
                found.append((idx, name))
        return [name for _idx, name in sorted(found, key=lambda item: item[0])]

    def card_play_event_from_line(line: str) -> Dict | None:
        if not line:
            return None
        lower = line.lower()
        names = player_names_in_line(line)
        primary = names[0] if names else player_name_from_line(line)
        if not primary:
            return None

        if is_made_basket_line(line):
            summary = made_basket_summary(line) or f"{primary} made a shot."
            return {"player": primary, "players": [primary], "type": "MAKE", "title": summary, "line": line}

        if "misses" in lower or "missed" in lower or "off the mark" in lower or "won't go" in lower:
            if "free throw" in lower:
                return {"player": primary, "players": [primary], "type": "FT MISS", "title": f"{primary} missed a free throw.", "line": line}
            return {"player": primary, "players": [primary], "type": "MISS", "title": f"{primary} missed a shot.", "line": line}

        if "free throw" in lower and any(word in lower for word in ("knocks down", "makes", "hits", "drops", "good")):
            return {"player": primary, "players": [primary], "type": "FT MAKE", "title": f"{primary} made a free throw.", "line": line}

        if any(word in lower for word in ("blocks", "swats", "rejects")):
            defender = names[-1] if len(names) > 1 else primary
            return {"player": defender, "players": [defender], "type": "BLOCK", "title": f"{defender} blocked the shot.", "line": line}

        if any(word in lower for word in ("steals", "strips", "picks off", "intercepts", "takes it away")):
            thief = primary
            return {"player": thief, "players": [thief], "type": "STEAL", "title": f"{thief} forced a steal.", "line": line}

        return None

    def card_assist_candidate_from_line(line: str) -> Dict | None:
        if not line:
            return None
        lower = line.lower()
        names = player_names_in_line(line)
        if len(names) < 2:
            return None
        assist_words = (
            "finds", "delivers", "threads", "kicks it out", "swings it", "whips it",
            "fires a pass", "drops it off", "lobs it", "throws it up", "sets up",
            "moves it", "gives it up", "gets it to", "feeds it", "leads"
        )
        if any(word in lower for word in assist_words):
            return {"passer": names[0], "receiver": names[1], "line": line}
        return None

    def current_player_card_score_text() -> str:
        team_a = SIM_CONTEXT.get("teamA")
        team_b = SIM_CONTEXT.get("teamB")
        if team_a is None or team_b is None:
            return ""
        period = SIM_CONTEXT.get("period")
        period_time = SIM_CONTEXT.get("period_time")
        score = f"{team_a.score}-{team_b.score}"
        if isinstance(period, int) and isinstance(period_time, int):
            return f"Q{period} {format_time(period_time)} | {score}"
        return score

    def player_card_event_team_name(player_name: str) -> str:
        for team in (SIM_CONTEXT.get("teamA"), SIM_CONTEXT.get("teamB")):
            if team is None:
                continue
            if any(p.name == player_name for p in getattr(team, "roster", [])):
                return short_team_name(team)
        return ""

    def append_log(text):
        _, bottom = dashboard_play_log.yview()
        should_follow = bottom >= 0.98
        dashboard_play_log.configure(state="normal")
        dashboard_play_log.insert("end", text)
        cleaned = " ".join(str(text).strip().split())
        if cleaned:
            maybe_start_free_throw_trip(cleaned)
        if cleaned and maybe_update_free_throw_summary(cleaned):
            pass
        elif is_made_basket_line(cleaned):
            summary = made_basket_summary(cleaned)
            if summary:
                last_basket_var.set(summary)
        highlight_words = (
            "poster", "slams", "dunk", "blocks", "swats", "ankle", "buzzer",
            "clutch", "flagrant", "clear path", "transition take", "steal",
            "vicious", "detonates", "chasedown", "heat check"
        )
        if cleaned and any(word in cleaned.lower() for word in highlight_words):
            top_play_lines.append(cleaned[:180])
            del top_play_lines[:-12]
        assist_candidate = card_assist_candidate_from_line(cleaned)
        if assist_candidate:
            pending_player_card_assist.update(assist_candidate)

        event = card_play_event_from_line(cleaned)
        if event:
            score_text = current_player_card_score_text()
            event["score"] = score_text
            event["team"] = player_card_event_team_name(event.get("player", ""))
            if event.get("type") == "MAKE":
                passer = pending_player_card_assist.get("passer")
                receiver = pending_player_card_assist.get("receiver")
                if passer and receiver == event.get("player") and passer != receiver:
                    player_card_play_events.append({
                        "player": passer,
                        "players": [passer],
                        "type": "ASSIST",
                        "title": f"{passer} assisted {receiver}.",
                        "line": pending_player_card_assist.get("line", ""),
                        "score": score_text,
                        "team": player_card_event_team_name(passer),
                    })
                pending_player_card_assist.update({"passer": None, "receiver": None, "line": ""})
            elif event.get("type") in ("MISS", "FT MISS", "STEAL"):
                pending_player_card_assist.update({"passer": None, "receiver": None, "line": ""})
            player_card_play_events.append(event)
            del player_card_play_events[:-160]
        if should_follow:
            dashboard_play_log.see("end")
        dashboard_play_log.configure(state="disabled")

    def parse_playoff_bracket_rows(bracket_text: str) -> List[Dict[str, str]]:
        rows = []
        current_round = ""
        round_names = {"ROUND 1", "QUARTERFINALS", "SEMIFINALS", "FINALS", "GOLD MEDAL GAME", "GROUP A", "GROUP B", "GROUP C", "KNOCKOUT SEEDS"}
        pending_by_round = {}
        for raw_line in (bracket_text or "").splitlines():
            line = raw_line.strip()
            if not line or set(line) <= {"=", "-", "#"}:
                continue
            upper = line.upper()
            if upper in round_names:
                current_round = line.title()
                pending_by_round.setdefault(current_round, [])
                rows.append({"round": current_round, "series": "", "matchup": "", "winner": "", "status": "Round"})
                continue
            if upper.startswith("CUSTOM 16-TEAM PLAYOFFS") or upper.startswith("OLYMPIC/FIBA TOURNAMENT"):
                label = "Olympic/FIBA Tournament" if upper.startswith("OLYMPIC") else "Custom 16-Team Playoffs"
                rows.append({"round": "Field", "series": "", "matchup": label, "winner": "", "status": "Ready"})
                continue
            if upper.startswith("CHAMPION:") or upper.startswith("GOLD MEDAL:"):
                champion = line.split(":", 1)[1].strip()
                status = "Gold" if upper.startswith("GOLD MEDAL:") else "Champion"
                rows.append({"round": status, "series": "", "matchup": champion, "winner": champion, "status": status})
                continue
            matchup = re.match(r"(\d+)\.\s+(.+?)\s+vs\s+(.+)$", line)
            if matchup:
                series_num, team_a, team_b = matchup.groups()
                row = {"round": current_round or "Round", "series": series_num, "matchup": f"{team_a} vs {team_b}", "winner": "", "status": "Pending"}
                rows.append(row)
                pending_by_round.setdefault(current_round or "Round", []).append(row)
                continue
            seed = re.match(r"(\d+)\.\s+(.+?)\s+\((.+)\)$", line)
            if seed and "SEEDS" in (current_round or "").upper():
                seed_num, team_name, status = seed.groups()
                rows.append({"round": current_round, "series": seed_num, "matchup": team_name, "winner": "", "status": status})
                continue
            winner = re.match(r"Winner:\s+(.+?)\s+over\s+(.+?)(?:\s+\((.+)\))?$", line)
            if winner:
                winner_name, loser_name, score = winner.groups()
                queue = pending_by_round.get(current_round or "Round", [])
                target = next((row for row in queue if not row.get("winner")), None)
                if target is not None:
                    target["winner"] = winner_name
                    target["status"] = f"over {loser_name}" + (f" ({score})" if score else "")
                else:
                    rows.append({"round": current_round or "Round", "series": "", "matchup": f"{winner_name} over {loser_name}", "winner": winner_name, "status": score or "Final"})
                continue
        return rows

    def update_bracket_widget(bracket_text: str):
        bracket_tree.delete(*bracket_tree.get_children())
        rows = parse_playoff_bracket_rows(bracket_text)
        if not rows:
            bracket_tree.insert("", "end", values=("", "", "Run a playoff series or full playoffs to fill the bracket.", "", ""))
            bracket_info_var.set("Run a playoff series or full playoffs to fill the interactive bracket.")
            return
        for row in rows:
            tags = ("round",) if row.get("status") == "Round" else ()
            bracket_tree.insert(
                "",
                "end",
                values=(row.get("round", ""), row.get("series", ""), row.get("matchup", ""), row.get("winner", ""), row.get("status", "")),
                tags=tags,
            )
        bracket_info_var.set("Select a matchup row to inspect the series. Winners fill in as the sim advances.")

    def on_bracket_select(_event=None):
        selection = bracket_tree.selection()
        if not selection:
            return
        values = bracket_tree.item(selection[0], "values")
        if not values:
            return
        round_name, series_num, matchup, winner, status = (list(values) + ["", "", "", "", ""])[:5]
        if winner:
            bracket_info_var.set(f"{round_name} {series_num}: {winner} advanced {status}.")
        elif matchup:
            bracket_info_var.set(f"{round_name} {series_num}: {matchup} - {status}.")

    bracket_tree.bind("<<TreeviewSelect>>", on_bracket_select)

