    def series_ts_value(stats: Dict) -> float:
        denom = 2 * (stats.get("fga", 0) + 0.44 * stats.get("fta", 0))
        return 0.0 if denom == 0 else 100 * stats.get("pts", 0) / denom

    def stat_pct_value(stats: Dict, made_key: str, att_key: str) -> float:
        return safe_pct(stats.get(made_key, 0), stats.get(att_key, 0))

    def advanced_sort_key(row: Dict) -> float:
        sort_mode = advanced_sort_var.get()
        if sort_mode == "PER":
            return row.get("per", 0.0)
        if sort_mode == "TS%":
            return row.get("ts", 0.0)
        if sort_mode == "PTS Created":
            return row.get("points_created", 0.0)
        if sort_mode == "USG%":
            return row.get("usg", 0.0)
        if sort_mode == "BPM":
            return row.get("bpm", 0.0)
        if sort_mode == "VORP":
            return row.get("vorp", 0.0)
        if sort_mode == "Off Impact":
            return row.get("off_impact", 0.0)
        if sort_mode == "Def Impact":
            return row.get("def_impact", 0.0)
        if sort_mode == "Total Impact":
            return row.get("total_impact", 0.0)
        if sort_mode == "+/-":
            return row.get("plus_minus_pg", 0.0)
        if sort_mode == "Double Teams":
            return row.get("double_teams_pg", 0.0)
        return row.get("minutes", 0.0)

