    def diet_total_text(diet: Dict) -> str:
        return diet_total_for_keys(
            diet,
            ("three", "mid", "rim", "post", "dunk")
        )

    def diet_total_for_keys(diet: Dict, keys: Tuple[str, ...]) -> str:
        made = sum(diet.get(f"{key}_made", 0) for key in keys)
        attempts = sum(diet.get(key, 0) for key in keys)
        return f"{made}/{attempts} {safe_pct(made, attempts):.0f}%"

    def live_diet_totals() -> Dict:
        totals = {}
        for team in (SIM_CONTEXT.get("teamA"), SIM_CONTEXT.get("teamB")):
            if team is None:
                continue
            team_bucket = {}
            for p in team.roster:
                team_bucket[player_stat_key(team, p)] = {
                    "minutes": p.minutes,
                    "shot_diet": dict(getattr(p, "shot_diet", {})),
                    "quarter_shot_diet": {q: dict(d) for q, d in (getattr(p, "quarter_shot_diet", {}) or {}).items()},
                    "defended_diet": dict(getattr(p, "defended_diet", {})),
                    "defended_matchup_diet": {name: dict(diet) for name, diet in (getattr(p, "defended_matchup_diet", {}) or {}).items()},
                }
            totals[team.name] = team_bucket
        return totals

    def apply_quarter_filter(totals: Dict, quarter: str) -> Dict:
        if quarter in (None, "All Quarters"):
            return totals
        q_key = 5 if quarter == "OT" else {"Q1": 1, "Q2": 2, "Q3": 3, "Q4": 4}.get(quarter)
        if q_key is None:
            return totals
        filtered = {}
        for team_name, players in totals.items():
            team_bucket = {}
            for name, stats in players.items():
                q_diet = (stats.get("quarter_shot_diet") or {}).get(q_key, {})
                team_bucket[name] = {**stats, "shot_diet": dict(q_diet)}
            filtered[team_name] = team_bucket
        return filtered

    def game_diet_totals(sections: Dict, selected: str, kind: str, quarter: str = "All Quarters") -> Dict:
        if selected == "All Games":
            totals = sections.get("_season_player_totals") or sections.get("_series_totals") or live_diet_totals()
            return apply_quarter_filter(totals, quarter)
        try:
            game_num = int(selected.replace("Game", "").strip())
        except ValueError:
            return apply_quarter_filter(sections.get("_season_player_totals") or sections.get("_series_totals") or live_diet_totals(), quarter)
        for game in sections.get("_game_logs", []) or []:
            if game.get("game_num") != game_num:
                continue
            totals = {}
            for team in game.get("teams", []):
                team_bucket = {}
                for p in team.get("players", []):
                    team_bucket[p.get("name", "")] = {
                        "minutes": p.get("minutes", 0),
                        "shot_diet": dict(p.get("shot_diet", {}) or {}),
                        "quarter_shot_diet": {q: dict(d) for q, d in (p.get("quarter_shot_diet", {}) or {}).items()},
                        "defended_diet": dict(p.get("defended_diet", {}) or {}),
                        "defended_matchup_diet": {name: dict(diet) for name, diet in (p.get("defended_matchup_diet", {}) or {}).items()},
                    }
                totals[team.get("name", "")] = team_bucket
            return apply_quarter_filter(totals, quarter)
        return apply_quarter_filter(sections.get("_season_player_totals") or sections.get("_series_totals") or live_diet_totals(), quarter)

    def filter_diet_totals_by_team(totals: Dict, selected_team: str) -> Dict:
        if selected_team == "All Teams":
            return totals
        return {selected_team: totals.get(selected_team, {})} if selected_team in totals else {}

    def update_diet_filter_dropdowns(sections: Dict):
        game_logs = sections.get("_game_logs", []) or []
        values = ["All Games"] + [f"Game {game.get('game_num')}" for game in game_logs if game.get("game_num")]
        values = tuple(dict.fromkeys(values))
        for dropdown, var in ((shot_filter_dropdown, shot_filter_var), (defense_filter_dropdown, defense_filter_var)):
            dropdown.configure(values=values or ("All Games",))
            if var.get() not in values:
                var.set("All Games")
        active_totals = game_diet_totals(sections, shot_filter_var.get(), "shot", shot_quarter_filter_var.get())
        team_values = tuple(["All Teams"] + list(active_totals.keys()))
        shot_team_filter_dropdown.configure(values=team_values or ("All Teams",))
        if shot_team_filter_var.get() not in team_values:
            shot_team_filter_var.set("All Teams")

        filtered_totals = filter_diet_totals_by_team(active_totals, shot_team_filter_var.get())
        defenders = ["All Defenders"]
        guarded = ["All Guarded"]
        guarded_seen = set()
        for _team_name, players in filtered_totals.items():
            for defender_name, stats in players.items():
                matchup_diet = stats.get("defended_matchup_diet", {}) or {}
                if matchup_diet:
                    defenders.append(defender_name)
                for guarded_name in matchup_diet.keys():
                    if guarded_name not in guarded_seen:
                        guarded.append(guarded_name)
                        guarded_seen.add(guarded_name)
        defender_values = tuple(dict.fromkeys(defenders))
        guarded_values = tuple(guarded)
        matchup_defender_dropdown.configure(values=defender_values or ("All Defenders",))
        matchup_guarded_dropdown.configure(values=guarded_values or ("All Guarded",))
        if matchup_defender_var.get() not in defender_values:
            matchup_defender_var.set("All Defenders")
        if matchup_guarded_var.get() not in guarded_values:
            matchup_guarded_var.set("All Guarded")

