    def period_average_label(period: int | None) -> str:
        if period is None:
            return "SERIES AVG"
        if period == 5:
            return "OT AVG"
        return f"Q{period} AVG"

    def aggregate_team_period_totals(players: Dict, period: int) -> Dict[str, float]:
        totals = {
            "games": 0, "minutes": 0, "pts": 0, "reb": 0, "ast": 0, "stl": 0, "blk": 0,
            "tov": 0, "oreb": 0, "fgm": 0, "fga": 0, "tpm": 0, "tpa": 0, "ftm": 0, "fta": 0,
        }
        for stats in players.values():
            quarter_stats = stats.get("quarter_stats") or {}
            if period == 5:
                q_rows = [row for q_num, row in quarter_stats.items() if q_num >= 5]
                q_stats = merge_period_rows(q_rows) if q_rows else {}
                q_stats["games"] = max((row.get("games", 0) for row in q_rows), default=0)
            else:
                q_stats = quarter_stats.get(period, {})
            if not q_stats:
                continue
            totals["games"] = max(totals["games"], q_stats.get("games", 0))
            for key in totals:
                if key != "games":
                    totals[key] += q_stats.get(key, 0)
        return totals

