    def insert_average_rows(tree, series_totals: Dict, series_team_totals: Dict, selected_team: str = "All Teams", period: int | None = None):
        tree.delete(*tree.get_children())
        if not series_totals and not series_team_totals:
            tree.insert("", "end", values=("", "Averages will appear here after games are played.", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", ""))
            return
        team_names_for_view = list(series_team_totals.keys() if period is None else series_totals.keys())
        if selected_team != "All Teams":
            source = series_team_totals if period is None else series_totals
            team_names_for_view = [selected_team] if selected_team in source else []
        for team_name in team_names_for_view:
            team_players = series_totals.get(team_name, {}) or {}
            if period is None:
                totals = series_team_totals.get(team_name, {})
            else:
                totals = aggregate_team_period_totals(team_players, period)
            games = max(1, totals.get("games", 0))
            team_display = table_player_name(team_name, 24)
            tree.insert(
                "",
                "end",
                values=(
                    team_display, period_average_label(period), games, "--",
                    f"{totals.get('pts', 0) / games:.1f}",
                    f"{totals.get('reb', 0) / games:.1f}",
                    f"{totals.get('oreb', 0) / games:.1f}",
                    f"{totals.get('ast', 0) / games:.1f}",
                    f"{totals.get('stl', 0) / games:.1f}",
                    f"{totals.get('blk', 0) / games:.1f}",
                    f"{totals.get('tov', 0) / games:.1f}",
                    f"{totals.get('fgm', 0) / games:.1f}/{totals.get('fga', 0) / games:.1f}",
                    f"{stat_pct_value(totals, 'fgm', 'fga'):.1f}",
                    f"{totals.get('tpm', 0) / games:.1f}/{totals.get('tpa', 0) / games:.1f}",
                    f"{stat_pct_value(totals, 'tpm', 'tpa'):.1f}",
                    f"{totals.get('ftm', 0) / games:.1f}/{totals.get('fta', 0) / games:.1f}",
                    f"{stat_pct_value(totals, 'ftm', 'fta'):.1f}",
                    f"{series_ts_value(totals):.1f}",
                    f"{totals.get('plus_minus', 0) / games:+.1f}",
                ),
                tags=("team",),
            )
            rows = []
            for name, stats in (team_players or {}).items():
                if period is None:
                    row_stats = stats
                elif period == 5:
                    q_rows = [row for q_num, row in (stats.get("quarter_stats") or {}).items() if q_num >= 5]
                    row_stats = merge_period_rows(q_rows) if q_rows else {}
                    if row_stats:
                        row_stats["games"] = max((row.get("games", 0) for row in q_rows), default=0)
                else:
                    row_stats = (stats.get("quarter_stats") or {}).get(period, {})
                if row_stats:
                    rows.append((name, row_stats))
            for name, stats in sorted(
                rows,
                key=lambda item: item[1].get("pts", 0) / max(1, item[1].get("games", 1)),
                reverse=True,
            ):
                gp = max(1, stats.get("games", 0))
                tree.insert(
                    "",
                    "end",
                    values=(
                        team_display,
                        table_player_name(name, 24),
                        gp,
                        f"{stats.get('minutes', 0) / 60 / gp:.1f}",
                        f"{stats.get('pts', 0) / gp:.1f}",
                        f"{stats.get('reb', 0) / gp:.1f}",
                        f"{stats.get('oreb', 0) / gp:.1f}",
                        f"{stats.get('ast', 0) / gp:.1f}",
                        f"{stats.get('stl', 0) / gp:.1f}",
                        f"{stats.get('blk', 0) / gp:.1f}",
                        f"{stats.get('tov', 0) / gp:.1f}",
                        f"{stats.get('fgm', 0) / gp:.1f}/{stats.get('fga', 0) / gp:.1f}",
                        f"{stat_pct_value(stats, 'fgm', 'fga'):.1f}",
                        f"{stats.get('tpm', 0) / gp:.1f}/{stats.get('tpa', 0) / gp:.1f}",
                        f"{stat_pct_value(stats, 'tpm', 'tpa'):.1f}",
                        f"{stats.get('ftm', 0) / gp:.1f}/{stats.get('fta', 0) / gp:.1f}",
                        f"{stat_pct_value(stats, 'ftm', 'fta'):.1f}",
                        f"{series_ts_value(stats):.1f}",
                        f"{stats.get('plus_minus', 0) / gp:+.1f}",
                    ),
                )

