    def award_widget_rows(sections: Dict) -> List[Tuple[str, str, str]]:
        season_awards = sections.get("_season_awards")
        if season_awards:
            return list(season_awards)
        series_totals = sections.get("_series_totals") or {}
        winner_name = sections.get("_winner_name")
        rows = []
        winner_players = series_totals.get(winner_name, {}) if winner_name else {}
        if winner_players:
            name, stats = max(winner_players.items(), key=lambda item: series_player_score(item[1]))
            gp = max(1, stats.get("games", 0))
            rows.append(("Series MVP", name, f"{winner_name}\n{stats.get('pts', 0) / gp:.1f} PTS  •  {stats.get('reb', 0) / gp:.1f} REB  •  {stats.get('ast', 0) / gp:.1f} AST"))
        all_players = [
            (team_name, name, stats)
            for team_name, players in series_totals.items()
            for name, stats in players.items()
            if stats.get("games", 0) > 0
        ]
        if all_players:
            scorer = max(all_players, key=lambda item: item[2].get("pts", 0) / max(1, item[2].get("games", 1)))
            playmaker = max(all_players, key=lambda item: item[2].get("ast", 0) / max(1, item[2].get("games", 1)))
            defender = max(all_players, key=lambda item: (item[2].get("stl", 0) + item[2].get("blk", 0)) / max(1, item[2].get("games", 1)))
            rows.append(("Scoring Leader", scorer[1], f"{scorer[0]}\n{scorer[2].get('pts', 0) / max(1, scorer[2].get('games', 1)):.1f} PPG  •  {series_ts_value(scorer[2]):.1f} TS%"))
            rows.append(("Playmaking Leader", playmaker[1], f"{playmaker[0]}\n{playmaker[2].get('ast', 0) / max(1, playmaker[2].get('games', 1)):.1f} APG"))
            rows.append(("Defensive Playmaker", defender[1], f"{defender[0]}\n{(defender[2].get('stl', 0) + defender[2].get('blk', 0)) / max(1, defender[2].get('games', 1)):.1f} stocks/game"))
        return rows

    def update_series_award_widgets(sections: Dict):
        rows = award_widget_rows(sections)
        row_by_award = {title: (name, stat) for title, name, stat in rows}
        fixed_awards = ("Series MVP", "Scoring Leader", "Playmaking Leader", "Defensive Playmaker")
        for idx, (canvas, title_var, name_var, stat_var) in enumerate(award_cards):
            award_name = fixed_awards[idx]
            title_var.set(award_name)
            if award_name in row_by_award:
                name, stat = row_by_award[award_name]
                if " | " in stat:
                    first, *rest = stat.split(" | ")
                    stat = first + ("\n" + "  •  ".join(rest) if rest else "")
                name_var.set(name)
                stat_var.set(stat)
                draw_named_headshot(canvas, name)
            else:
                draw_named_headshot(canvas, "")
                name_var.set("Waiting for series...")
                stat_var.set("")

