    def live_quarter_team_row(team: Team) -> Dict[str, float]:
        keys = (
            "score", "reb", "ast", "tov", "fgm", "fga", "tpm", "tpa",
            "oreb", "dreb", "stl", "blk", "pf", "ftm", "fta"
        )
        current = team_quarter_snapshot(team)
        completed = getattr(team, "quarter_team_stats", []) or []
        row = {}
        for key in keys:
            row[key] = current.get(key, 0) - sum(q.get(key, 0) for q in completed)
        return row

    def live_quarter_player_row(team: Team, player: Player) -> Dict[str, float]:
        player_key = player_stat_key(team, player)
        current = player_quarter_snapshot(team).get(player_key, {})
        completed_rows = getattr(team, "quarter_player_stats", {}).get(player_key, []) or []
        row = {}
        for key in (
            "minutes", "pts", "reb", "ast", "stl", "blk", "tov", "oreb", "dreb",
            "pf", "fgm", "fga", "tpm", "tpa", "ftm", "fta", "plus_minus"
        ):
            row[key] = current.get(key, 0) - sum(q.get(key, 0) for q in completed_rows)
        row["shot_diet"] = diet_minus_completed(current.get("shot_diet", {}), completed_rows, "shot_diet")
        row["defended_diet"] = diet_minus_completed(current.get("defended_diet", {}), completed_rows, "defended_diet")
        return row

    def blank_period_box_row() -> Dict[str, float]:
        return {
            "minutes": 0, "pts": 0, "reb": 0, "ast": 0, "stl": 0, "blk": 0, "tov": 0,
            "oreb": 0, "dreb": 0, "pf": 0, "fgm": 0, "fga": 0, "tpm": 0, "tpa": 0,
            "ftm": 0, "fta": 0, "plus_minus": 0, "score": 0,
        }

    def merge_period_rows(rows: List[Dict[str, float]]) -> Dict[str, float]:
        merged = blank_period_box_row()
        for row in rows:
            for key in merged:
                merged[key] += row.get(key, 0)
        return merged

    def selected_period_rows(rows: List[Dict[str, float]], period: int) -> List[Dict[str, float]]:
        if period == 5:
            return [r for r in rows if r.get("period", 0) >= 5]
        return [r for r in rows if r.get("period") == period]

    def quarter_box_values(team: Team, player: Player, row: Dict[str, float]):
        fgm = row.get("fgm", 0)
        fga = row.get("fga", 0)
        tpm = row.get("tpm", 0)
        tpa = row.get("tpa", 0)
        ftm = row.get("ftm", 0)
        fta = row.get("fta", 0)
        pts = row.get("pts", 0)
        ts_denom = 2 * (fga + 0.44 * fta)
        ts = 0.0 if ts_denom == 0 else round(100 * pts / ts_denom, 1)
        return (
            short_team_name(team),
            player.position,
            table_player_name(player.name, 24),
            f"{row.get('minutes', 0) / 60:.1f}",
            int(pts),
            int(row.get("reb", 0)),
            int(row.get("ast", 0)),
            int(row.get("stl", 0)),
            int(row.get("blk", 0)),
            int(row.get("tov", 0)),
            int(row.get("oreb", 0)),
            int(row.get("dreb", 0)),
            int(row.get("pf", 0)),
            f"{int(row.get('plus_minus', 0)):+d}",
            f"{int(fgm)}/{int(fga)}",
            f"{int(tpm)}/{int(tpa)}",
            f"{int(ftm)}/{int(fta)}",
            f"{safe_pct(fgm, fga):.1f}",
            f"{safe_pct(tpm, tpa):.1f}",
            f"{safe_pct(ftm, fta):.1f}",
            f"{ts:.1f}",
        )

    def update_quarter_tabs():
        team_a = SIM_CONTEXT.get("teamA")
        team_b = SIM_CONTEXT.get("teamB")
        selected_quarter = str(quarter_view_var.get())
        if selected_quarter == "OT":
            q = 5
        else:
            try:
                q = int(selected_quarter.replace("Q", ""))
            except ValueError:
                q = 1
            q = max(1, min(4, q))
        q_tree.delete(*q_tree.get_children())
        if team_a is None or team_b is None:
            q_tree.insert("", "end", values=("", "", "Quarter box scores will appear here.", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", ""))
            return
        for team in (team_a, team_b):
            if q == 5:
                team_rows = selected_period_rows(getattr(team, "quarter_team_stats", []) or [], q)
                if SIM_CONTEXT.get("period", 0) >= 5:
                    team_rows.append(live_quarter_team_row(team))
                team_header = merge_period_rows(team_rows) if team_rows else None
            else:
                team_header = live_quarter_team_row(team) if SIM_CONTEXT.get("period") == q else next(
                    (r for r in (getattr(team, "quarter_team_stats", []) or []) if r.get("period") == q),
                    None
                )
            if team_header:
                header_label = (
                    f"{selected_quarter} TEAM | PTS {team_header.get('score', 0)} | "
                    f"REB {team_header.get('reb', 0)} | AST {team_header.get('ast', 0)} | "
                    f"FG {team_header.get('fgm', 0)}/{team_header.get('fga', 0)}"
                )
            else:
                header_label = f"{selected_quarter} TEAM"
            q_tree.insert("", "end", values=(short_team_name(team), "", header_label, "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", ""), tags=("team",))

            quarter_rows = getattr(team, "quarter_player_stats", {}) or {}
            inserted = False
            for p in box_score_player_order(team, final=False):
                row = next((r for r in quarter_rows.get(p.name, []) if r.get("period") == q), None)
                if row is None and SIM_CONTEXT.get("period") == q:
                    row = live_quarter_player_row(team, p)
                if row is None:
                    continue
                if row.get("minutes", 0) <= 0 and not any(row.get(key, 0) for key in ("pts", "reb", "ast", "stl", "blk", "tov", "fgm", "fga", "fta")):
                    continue
                q_tree.insert("", "end", values=quarter_box_values(team, p, row))
                inserted = True
            if not inserted:
                q_tree.insert("", "end", values=(short_team_name(team), "", "No player quarter stats yet.", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", ""))

    def set_text_widget(widget, text: str):
        widget.configure(state="normal")
        widget.delete("1.0", "end")
        widget.insert("end", text)
        widget.configure(state="disabled")

    def short_team_name(team: Team | None) -> str:
        if team is None:
            return "-"
        name = team.name
        if len(name) > 24:
            return table_player_name(name, 24)
        return name

    def diet_line(team: Team, label: str, key: str) -> str:
        diet = getattr(team, "shot_diet", {}) or {}
        att = int(diet.get(key, 0))
        made = int(diet.get(f"{key}_made", 0))
        pct = safe_pct(made, att)
        return f"{label:<8} {made:>2}/{att:<2} {pct:>5.1f}%"

    def team_shot_chart_text(team: Team) -> str:
        if team is None:
            return ""
        diet = getattr(team, "shot_diet", {}) or {}
        q_count = max(1, diet.get("shot_quality_count", 0))
        q_avg = diet.get("shot_quality_sum", 0.0) / q_count if diet.get("shot_quality_count", 0) else 0.0
        lines = [
            short_team_name(team),
            diet_line(team, "3PT", "three"),
            diet_line(team, "MID", "mid"),
            diet_line(team, "RIM", "rim"),
            diet_line(team, "POST", "post"),
            diet_line(team, "DUNK", "dunk"),
            diet_line(team, "C&S", "catch_shoot"),
            diet_line(team, "ISO", "iso"),
            diet_line(team, "PUTB", "putback"),
            diet_line(team, "FB", "fastbreak"),
            f"ShotQ   {q_avg:>5.2f}",
        ]
        return "\n".join(lines)

    def top_players_by(team: Team, stat_name: str, attr_name: str, count: int = 3) -> str:
        rows = sorted(team.roster, key=lambda p: getattr(p, attr_name), reverse=True)[:count]
        return f"{stat_name}: " + ", ".join(f"{table_player_name(p.name, 15)} {getattr(p, attr_name)}" for p in rows)

    def live_leaders_text(team_a: Team, team_b: Team) -> str:
        if team_a is None or team_b is None:
            return "Game leaders will appear once the game starts."
        all_players = team_a.roster + team_b.roster
        categories = (
            ("PTS", "pts"),
            ("REB", "reb"),
            ("AST", "ast"),
            ("STL", "stl"),
            ("BLK", "blk_stat"),
            ("+/-", "plus_minus"),
        )
        lines = []
        for label, attr in categories:
            leader = max(all_players, key=lambda p: getattr(p, attr))
            value = getattr(leader, attr)
            plus = f"{value:+d}" if attr == "plus_minus" else str(value)
            lines.append(f"{label:<3} {table_player_name(leader.name, 18):<18} {plus:>4}")
        return "\n".join(lines)

    def hot_cold_indicator_text(team_a: Team, team_b: Team) -> str:
        if team_a is None or team_b is None:
            return "No hot/cold indicators yet."
        rows = []
        for p in sorted(team_a.roster + team_b.roster, key=lambda player: (getattr(player, "hot_streak", 0), getattr(player, "fga", 0)), reverse=True):
            hot = getattr(p, "hot_streak", 0)
            cold = getattr(p, "cold_streak", 0)
            if hot >= 2:
                rows.append(f"HOT  {table_player_name(p.name, 18)} {hot} straight makes")
            elif cold >= 3:
                rows.append(f"COLD {table_player_name(p.name, 18)} {cold} straight misses")
        return " | ".join(rows[:4]) if rows else "No major hot/cold swing yet."

    def clutch_shot_chart_text(team_a: Team, team_b: Team) -> str:
        if team_a is None or team_b is None:
            return "Clutch chart starts in close 4th quarters."
        lines = []
        for team in (team_a, team_b):
            diet = getattr(team, "clutch_shot_diet", {}) or {}
            attempts = sum(diet.get(k, 0) for k in ("three", "mid", "rim", "post", "dunk"))
            if attempts <= 0:
                lines.append(f"{short_team_name(team)} clutch: 0/0")
            else:
                made = sum(diet.get(f"{k}_made", 0) for k in ("three", "mid", "rim", "post", "dunk"))
                lines.append(
                    f"{short_team_name(team)} clutch {made}/{attempts} | "
                    f"3P {format_diet_pair_compact(diet, 'three')} | "
                    f"MID {format_diet_pair_compact(diet, 'mid')} | "
                    f"RIM {format_diet_group_compact(diet, ('rim', 'dunk'))}"
                )
        return " || ".join(lines)

    def spotlight_text(team_a: Team, team_b: Team) -> str:
        if team_a is None or team_b is None:
            return "No spotlight yet."
        all_players = team_a.roster + team_b.roster
        player = max(
            all_players,
            key=lambda p: p.pts * 1.8 + p.ast * 1.2 + p.reb * 0.8 + p.stl * 1.5 + p.blk_stat * 1.5 + p.plus_minus * 0.18
        )
        fg = f"{player.fgm}/{player.fga}"
        tp = f"{player.tpm}/{player.tpa}"
        return (
            f"{player.name}\n"
            f"{player.pts} PTS  {player.reb} REB  {player.ast} AST  {player.plus_minus:+d}\n"
            f"FG {fg} | 3P {tp} | PF {player.pf}"
        )

    def foul_trouble_text(team_a: Team, team_b: Team) -> str:
        if team_a is None or team_b is None:
            return "Foul trouble will appear here."
        rows = []
        for team in (team_a, team_b):
            tagged = [p for p in team.roster if p.pf >= 2 or getattr(p, "foul_rest_until", 0) > SIM_CONTEXT.get("period", 1)]
            if tagged:
                rows.append(short_team_name(team))
                rows.extend(f"  {table_player_name(p.name, 18):<18} PF {p.pf}" for p in sorted(tagged, key=lambda p: p.pf, reverse=True))
        return "\n".join(rows) if rows else "No major foul trouble."

    def quarter_dashboard_text(team_a: Team, team_b: Team) -> str:
        if team_a is None or team_b is None:
            return "Quarter stats will fill in as quarters end."
        lines = []
        for team in (team_a, team_b):
            lines.append(short_team_name(team))
            rows = getattr(team, "quarter_team_stats", []) or []
            if not rows:
                lines.append("  No completed quarters yet.")
            for row in rows[-4:]:
                lines.append(
                    f"  Q{row.get('period', '-')}: {row.get('score', 0)} pts, "
                    f"{row.get('reb', 0)} reb, {row.get('ast', 0)} ast, "
                    f"{row.get('fgm', 0)}/{row.get('fga', 0)} FG"
                )
        return "\n".join(lines)

    def bracket_text() -> str:
        if not series_game_results:
            return "Series game tiles will appear here."
        return " | ".join(series_game_results[-7:])

    def live_win_probability(team_a: Team | None, team_b: Team | None) -> float:
        if team_a is None or team_b is None:
            return 50.0
        period = SIM_CONTEXT.get("period", 1)
        period_time = SIM_CONTEXT.get("period_time", GAME_SECONDS // 4)
        remaining = max(0, (4 - min(period, 4)) * rules_quarter_seconds() + period_time)
        remaining_ratio = max(0.0, min(1.0, remaining / max(1, rules_game_seconds())))
        score_scale = 5.2 + 14.5 * (remaining_ratio ** 0.72)
        if remaining <= 60:
            score_scale = max(3.8, score_scale - 0.65)
        score_edge = (team_a.score - team_b.score) / score_scale

        def live_team_edge(team: Team, opp: Team) -> float:
            team_tot = accumulate_team_totals(team)
            opp_tot = accumulate_team_totals(opp)
            team_poss = max(1.0, team_tot["fga"] + 0.44 * team_tot["fta"] - team_tot["oreb"] + team_tot["tov"])
            opp_poss = max(1.0, opp_tot["fga"] + 0.44 * opp_tot["fta"] - opp_tot["oreb"] + opp_tot["tov"])
            team_efg = safe_div(team_tot["fgm"] + 0.5 * team_tot["tpm"], team_tot["fga"])
            opp_efg = safe_div(opp_tot["fgm"] + 0.5 * opp_tot["tpm"], opp_tot["fga"])
            team_ts = safe_div(team.score, 2 * (team_tot["fga"] + 0.44 * team_tot["fta"]))
            opp_ts = safe_div(opp.score, 2 * (opp_tot["fga"] + 0.44 * opp_tot["fta"]))
            team_tov_rate = safe_div(team_tot["tov"], team_poss)
            opp_tov_rate = safe_div(opp_tot["tov"], opp_poss)
            orb_share = safe_div(team_tot["oreb"], team_tot["oreb"] + opp_tot["dreb"])
            dreb_share = safe_div(team_tot["dreb"], team_tot["dreb"] + opp_tot["oreb"])
            ast_rate = safe_div(team_tot["ast"], max(1, team_tot["fgm"]))
            stocks_rate = safe_div(team_tot["stl"] + team_tot["blk"], team_poss)
            off_rating = safe_div(team.score, team_poss)
            def_rating = safe_div(opp.score, opp_poss)
            core_players = sorted(team.roster, key=overall_rating, reverse=True)[:8]
            roster_quality = safe_div(sum(overall_rating(p) for p in core_players), max(1, len(core_players)))
            live_sample = min(1.0, (team_tot["fga"] + opp_tot["fga"]) / 70.0)
            live_value = (
                (off_rating - 1.08) * 3.6
                + (1.08 - def_rating) * 3.0
                + (team_efg - 0.53) * 2.8
                + (team_ts - 0.57) * 2.0
                + (0.53 - opp_efg) * 2.2
                + (opp_tov_rate - team_tov_rate) * 1.8
                + (orb_share - 0.25) * 0.75
                + (dreb_share - 0.74) * 0.70
                + (ast_rate - 0.58) * 0.32
                + stocks_rate * 1.4
            )
            roster_value = (roster_quality - 0.84) * 2.2
            return live_value * live_sample + roster_value * (1.0 - 0.45 * live_sample)

        metric_edge = live_team_edge(team_a, team_b) - live_team_edge(team_b, team_a)
        metric_weight = 0.28 + 0.62 * remaining_ratio
        metric_edge = clamp_value(metric_edge * metric_weight, -1.15, 1.15)
        possession = SIM_CONTEXT.get("possession")
        possession_edge = 0.0
        if possession is team_a:
            possession_edge = 0.08 + 0.08 * (1.0 - remaining_ratio)
        elif possession is team_b:
            possession_edge = -0.08 - 0.08 * (1.0 - remaining_ratio)

        prob = 100.0 / (1.0 + math.exp(-(score_edge + metric_edge + possession_edge)))
        return max(2.0, min(98.0, prob))

    def update_scoreboard_extras():
        team_a = SIM_CONTEXT.get("teamA")
        team_b = SIM_CONTEXT.get("teamB")
        possession = SIM_CONTEXT.get("possession")
        if possession is team_a:
            possession_var.set(f"Possession: {short_team_name(team_a)}")
        elif possession is team_b:
            possession_var.set(f"Possession: {short_team_name(team_b)}")
        else:
            possession_var.set("Possession: -")

        prob_a = live_win_probability(team_a, team_b)
        win_prob_var.set(prob_a)
        if team_a is not None and team_b is not None:
            win_prob_label_var.set(f"Win prob: {short_team_name(team_a)} {prob_a:.0f}% / {short_team_name(team_b)} {100 - prob_a:.0f}%")
        else:
            win_prob_label_var.set("Win prob: 50 / 50")

    def spotlight_player(team_a: Team | None, team_b: Team | None) -> Player | None:
        if team_a is None or team_b is None:
            return None
        all_players = team_a.roster + team_b.roster
        return max(
            all_players,
            key=lambda p: p.pts * 1.8 + p.ast * 1.2 + p.reb * 0.8 + p.stl * 1.5 + p.blk_stat * 1.5 + p.plus_minus * 0.18
        )

    def shot_chart_options(team: Team | None) -> Tuple[str, ...]:
        if team is None:
            return ("Team",)
        return tuple(["Team"] + [p.name for p in team.roster])

    def sync_shot_chart_dropdown(dropdown, var: tk.StringVar, team: Team | None):
        values = shot_chart_options(team)
        dropdown.configure(values=values)
        if var.get() not in values:
            var.set("Team")

    def selected_shot_chart_subject(team: Team, var: tk.StringVar):
        choice = var.get()
        if choice and choice != "Team":
            for p in team.roster:
                if p.name == choice:
                    return p
        return team

    def shot_chart_subject_name(subject) -> str:
        if isinstance(subject, Player):
            return table_player_name(subject.name, 17)
        return "TEAM"

    def shot_chart_zone_values(subject, key: str) -> Tuple[int, int, float]:
        diet = getattr(subject, "shot_diet", {}) or {}
        if key == "rim_zone":
            att = int(diet.get("rim", 0)) + int(diet.get("dunk", 0))
            made = int(diet.get("rim_made", 0)) + int(diet.get("dunk_made", 0))
            return made, att, safe_pct(made, att)
        if key == "paint":
            att = int(diet.get("paint", 0))
            made = int(diet.get("paint_made", 0))
            if att == 0:
                att = int(diet.get("rim", 0))
                made = int(diet.get("rim_made", 0))
            return made, att, safe_pct(made, att)
        att = int(diet.get(key, 0))
        made = int(diet.get(f"{key}_made", 0))
        return made, att, safe_pct(made, att)

    def draw_live_shot_chart(team_a: Team | None, team_b: Team | None):
        shot_chart_canvas.delete("all")
        w = max(570, shot_chart_canvas.winfo_width())
        h = max(360, shot_chart_canvas.winfo_height())
        line_color = "#f8fafc"
        shot_chart_canvas.create_rectangle(0, 0, w, h, outline="", fill="#0b1120")
        court_w = 570
        court_h = 360
        court_x = max(0, (w - court_w) / 2)
        court_y = 0
        if os.path.exists(court_background_gui_path):
            try:
                if court_background_cache.get("image") is None:
                    court_background_cache["image"] = tk.PhotoImage(file=court_background_gui_path)
                shot_chart_canvas.create_image(court_x, court_y, anchor="nw", image=court_background_cache["image"])
            except Exception:
                shot_chart_canvas.create_rectangle(court_x, court_y, court_x + court_w, court_y + court_h, outline="#334155", fill="#9b7a55", width=2)
        else:
            shot_chart_canvas.create_rectangle(court_x, court_y, court_x + court_w, court_y + court_h, outline="#334155", fill="#9b7a55", width=2)
        title_x = w / 2
        title_y = court_y + 18
        shot_chart_canvas.create_rectangle(
            title_x - 62, title_y - 14,
            title_x + 62, title_y + 13,
            fill="#111827",
            outline="#475569",
            width=1,
        )
        shot_chart_canvas.create_text(title_x, title_y, text="Shot Chart", fill="#facc15", font=("Segoe UI", 14, "bold"))

        if team_a is None or team_b is None:
            shot_chart_canvas.create_text(w / 2, h / 2, text="Starts when game starts", fill="#cbd5e1", font=("Segoe UI", 12))
            return

        def zone_color(zone: str, pct: float, attempts: int) -> str:
            if attempts == 0:
                return "#4b5563"
            if zone == "rim":
                if pct > 50:
                    return "#24c449"
                if pct >= 40:
                    return "#c7a823"
                return "#e04444"
            if zone == "mid":
                if pct > 40:
                    return "#24c449"
                if pct >= 30:
                    return "#c7a823"
                return "#e04444"
            if pct >= 55:
                return "#24c449"
            if pct >= 42:
                return "#c7a823"
            if pct >= 33:
                return "#c7a823"
            return "#e04444"

        subject_a = selected_shot_chart_subject(team_a, shot_chart_a_var)
        subject_b = selected_shot_chart_subject(team_b, shot_chart_b_var)

        def zone_text(label: str, key: str, subject) -> str:
            made, att, pct = shot_chart_zone_values(subject, key)
            return f"{label}\n{made}/{att}\n{pct:.0f}%"

        def draw_chart_logo(team: Team, cx: float, cy: float, accent: str):
            image = load_team_logo(team.name)
            if image is not None:
                shot_chart_canvas.create_image(cx, cy, image=image)
                return
            flag_code = olympic_flag_code(team.name)
            if flag_code:
                draw_country_flag(shot_chart_canvas, flag_code, cx - 32, cy - 20, cx + 32, cy + 20)
                return
            shot_chart_canvas.create_oval(cx - 21, cy - 21, cx + 21, cy + 21, fill="#111827", outline=accent, width=3)
            shot_chart_canvas.create_text(cx, cy, text=team_initials(team.name), fill=accent, font=("Segoe UI", 11, "bold"))

        def draw_half(team: Team, subject, side_left: float, side_right: float, flip: bool, accent: str):
            side_w = side_right - side_left
            logo_x = side_left + side_w * (0.12 if not flip else 0.88)
            rim_x = side_left + side_w * (0.17 if not flip else 0.83)
            mid_x_text = side_left + side_w * (0.43 if not flip else 0.57)
            three_text_x = side_left + side_w * (0.66 if not flip else 0.34)

            made_3, att_3, pct_3 = shot_chart_zone_values(subject, "three")
            made_mid, att_mid, pct_mid = shot_chart_zone_values(subject, "mid")
            made_rim, att_rim, pct_rim = shot_chart_zone_values(subject, "rim_zone")

            three_fill = zone_color("three", pct_3, att_3)
            mid_fill = zone_color("mid", pct_mid, att_mid)
            rim_fill = zone_color("rim", pct_rim, att_rim)

            draw_chart_logo(team, logo_x, court_y + court_h * 0.15, accent)
            shot_chart_canvas.create_rectangle(
                logo_x - 52, court_y + court_h * 0.235,
                logo_x + 52, court_y + court_h * 0.295,
                fill="#111827",
                outline="#475569",
                width=1,
            )
            shot_chart_canvas.create_text(
                logo_x, court_y + court_h * 0.265,
                text=shot_chart_subject_name(subject),
                fill=accent,
                font=("Segoe UI", 9, "bold"),
                justify="center",
            )

            def zone_card(cx: float, cy: float, fill: str, text: str, wide: float = 66, tall: float = 48):
                shot_chart_canvas.create_rectangle(
                    cx - wide / 2, cy - tall / 2,
                    cx + wide / 2, cy + tall / 2,
                    fill=fill,
                    outline=line_color,
                    width=2,
                    stipple="gray50",
                )
                shot_chart_canvas.create_text(
                    cx, cy,
                    text=text,
                    fill="#ffffff",
                    font=("Segoe UI", 9, "bold"),
                    justify="center"
                )

            text_fill = "#ffffff"
            zone_card(three_text_x, court_y + court_h * 0.30, three_fill, zone_text("3PT", "three", subject), wide=70, tall=50)
            zone_card(mid_x_text, court_y + court_h * 0.73, mid_fill, zone_text("MID", "mid", subject), wide=62, tall=48)
            zone_card(rim_x, court_y + court_h * 0.53, rim_fill, zone_text("RIM", "paint", subject), wide=52, tall=44)

        draw_half(team_a, subject_a, court_x, court_x + court_w / 2, False, "#38bdf8")
        draw_half(team_b, subject_b, court_x + court_w / 2, court_x + court_w, True, "#fb7185")

    def draw_momentum_graph():
        momentum_canvas.delete("all")
        w = max(240, momentum_canvas.winfo_width())
        h = max(80, momentum_canvas.winfo_height())
        momentum_canvas.create_rectangle(6, 6, w - 6, h - 6, outline="#334155", fill="#0f172a")
        mid = h / 2
        momentum_canvas.create_line(10, mid, w - 10, mid, fill="#64748b")
        if len(score_history) < 2:
            momentum_canvas.create_text(w / 2, mid, text="Margin graph builds live", fill="#cbd5e1", font=("Segoe UI", 9))
            return
        margins = [item[2] for item in score_history[-80:]]
        max_margin = max(8, max(abs(m) for m in margins))
        points = []
        for i, margin in enumerate(margins):
            x = 10 + i * (w - 20) / max(1, len(margins) - 1)
            y = mid - (margin / max_margin) * (h * 0.38)
            points.extend((x, y))
        if len(points) >= 4:
            momentum_canvas.create_line(*points, fill="#facc15", width=2, smooth=True)
        momentum_canvas.create_text(34, 15, text=f"{margins[-1]:+d}", fill="#f8fafc", font=("Segoe UI", 9, "bold"))

    def spacing_grade(team: Team | None) -> str:
        if team is None or not getattr(team, "on_floor", None):
            return "-"
        shooters = sum(1 for p in team.on_floor if p.three_tendency >= 0.28 and p.three_rating >= 0.76)
        non_shooters = sum(1 for p in team.on_floor if p.three_tendency <= 0.10 and p.mid_tendency <= 0.12)
        if lineup_can_five_out(team):
            return "Elite"
        if shooters >= 4 and non_shooters == 0:
            return "Good"
        if shooters >= 3:
            return "OK"
        if non_shooters >= 2:
            return "Tight"
        return "Mixed"

    def team_defense_grade(team: Team | None) -> str:
        if team is None or not getattr(team, "on_floor", None):
            return "-"
        avg = sum(0.5 * p.perimeter_def + 0.5 * p.interior_def for p in team.on_floor) / max(1, len(team.on_floor))
        if avg >= 0.80:
            return "Elite"
        if avg >= 0.70:
            return "Good"
        if avg >= 0.60:
            return "OK"
        return "Weak"

    def current_focus_text(team: Team | None) -> str:
        if team is None:
            return "-"
        focus = getattr(team, "defensive_focus", None) or getattr(team, "series_defensive_focus", None)
        coverage = getattr(team, "manual_star_coverage", None)
        if focus and coverage:
            return f"{focus} / {plan_label(coverage)}"
        if focus:
            return str(focus)
        if coverage:
            return plan_label(coverage)
        return "Coach auto"

    def gui_player_position(player: Player | None) -> str:
        if player is None:
            return "-"
        pos = str(getattr(player, "position", "") or "").upper()
        return pos if pos in ("PG", "SG", "SF", "PF", "C") else "-"

    def update_rotation_widget():
        rotation_tree.delete(*rotation_tree.get_children())
        standings = (playoff_sections_state.get("sections") or {}).get("_season_standings") or []
        if standings:
            for row in standings:
                rotation_tree.insert(
                    "",
                    "end",
                    values=(
                        row.get("seed", ""),
                        row.get("conference", ""),
                        table_player_name(row.get("team", ""), 32),
                        row.get("wins", 0),
                        row.get("losses", 0),
                        f"{row.get('pct', 0):.3f}",
                        f"{row.get('pf', 0):.1f}",
                        f"{row.get('pa', 0):.1f}",
                        f"{row.get('diff', 0):+.1f}",
                        f"{row.get('strength', 0):.1f}",
                    ),
                )
            return
        teams = [SIM_CONTEXT.get("teamA"), SIM_CONTEXT.get("teamB")]
        if not all(teams):
            rotation_tree.insert("", "end", values=("", "", "Season standings will appear here after Season mode.", "", "", "", "", "", "", ""))
            return
        for team in teams:
            rotation_tree.insert("", "end", values=("", "-", short_team_name(team), "-", "-", "-", f"{team.score:.1f}", "-", "-", "Live"))

    def update_lineup_widget():
        lineup_tree.delete(*lineup_tree.get_children())
        teams = [SIM_CONTEXT.get("teamA"), SIM_CONTEXT.get("teamB")]
        if not all(teams):
            lineup_tree.insert("", "end", values=("", "", "", "", "", "Lineup plus-minus appears once a game starts."))
            return
        for team in teams:
            rows = []
            for key, row in (getattr(team, "lineup_plus_minus", {}) or {}).items():
                rows.append((key, row))
            if not rows:
                key = lineup_key(team)
                row = {"minutes": sum((p.minutes for p in getattr(team, "on_floor", []) or []), 0) / max(1, len(getattr(team, "on_floor", []) or [])), "plus_minus": 0, "pts_for": 0, "pts_against": 0}
                rows.append((key, row))
            for key, row in sorted(rows, key=lambda item: (item[1].get("plus_minus", 0), item[1].get("minutes", 0)), reverse=True)[:8]:
                lineup_tree.insert(
                    "",
                    "end",
                    values=(
                        short_team_name(team),
                        f"{row.get('plus_minus', 0):+d}",
                        f"{row.get('minutes', 0) / 60:.1f}",
                        row.get("pts_for", 0),
                        row.get("pts_against", 0),
                        " / ".join(table_player_name(name, 18) for name in key),
                    ),
                )

    def update_possession_widget():
        possession_tree.delete(*possession_tree.get_children())
        team_a = SIM_CONTEXT.get("teamA")
        team_b = SIM_CONTEXT.get("teamB")
        if team_a is None or team_b is None:
            possession_tree.insert("", "end", values=("Game State", "Waiting", "Possession tracker fills once the sim starts."))
            return
        possession = SIM_CONTEXT.get("possession")
        period = SIM_CONTEXT.get("period", "-")
        period_time = SIM_CONTEXT.get("period_time", 0)
        possession_tree.insert("", "end", values=("Clock", f"Q{period} {format_time(period_time) if isinstance(period_time, int) else '-'}", period_clock_var.get()))
        possession_tree.insert("", "end", values=("Possession", short_team_name(possession), possession_var.get()))
        possession_tree.insert("", "end", values=("Score", f"{team_a.score}-{team_b.score}", f"{short_team_name(team_a)} vs {short_team_name(team_b)}"))
        possession_tree.insert("", "end", values=("Win Prob", win_prob_label_var.get(), "Score, clock, possession, and live advanced edge"))
        possession_tree.insert("", "end", values=("Last Basket", "", last_basket_var.get()))
        possession_tree.insert("", "end", values=("Hot/Cold", "Live", hot_cold_indicator_text(team_a, team_b)))
        possession_tree.insert("", "end", values=("Clutch Chart", "4Q close", clutch_shot_chart_text(team_a, team_b)))
        for idx, item in enumerate(reversed(series_game_results[-5:]), start=1):
            possession_tree.insert("", "end", values=(f"Series G-{idx}", item, "Recent result"))

    def active_player_card_team() -> Team | None:
        team_a = SIM_CONTEXT.get("teamA")
        team_b = SIM_CONTEXT.get("teamB")
        selected = player_card_team_var.get()
        if team_b is not None and selected == team_b.name:
            return team_b
        if team_a is not None and selected == team_a.name:
            return team_a
        return team_a

    def sync_player_card_dropdown():
        team_a = SIM_CONTEXT.get("teamA")
        team_b = SIM_CONTEXT.get("teamB")
        team_names_for_card = tuple(t.name for t in (team_a, team_b) if t is not None)
        player_card_team_dropdown.configure(values=team_names_for_card)
        if team_names_for_card and player_card_team_var.get() not in team_names_for_card:
            player_card_team_var.set(team_names_for_card[0])
        elif not team_names_for_card:
            player_card_team_var.set("")
        team = active_player_card_team()
        values = tuple(player_stat_key(team, p) for p in team.roster) if team is not None else ()
        player_card_player_dropdown.configure(values=values)
        if values and player_card_player_var.get() not in values:
            player_card_player_var.set(values[0])
        elif not values:
            player_card_player_var.set("")

        game_logs = (playoff_sections_state.get("sections") or {}).get("_game_logs", []) or []
        game_values = ["Live"] + [f"Game {game.get('game_num')}" for game in game_logs if game.get("game_num")]
        game_values = tuple(dict.fromkeys(game_values))
        player_card_game_dropdown.configure(values=game_values or ("Live",))
        if player_card_game_var.get() not in game_values:
            player_card_game_var.set("Live")

    def player_card_game_snapshot_row(team: Team, player: Player) -> Dict[str, float] | None:
        selected = player_card_game_var.get()
        if not selected or selected == "Live":
            return None
        try:
            game_num = int(selected.replace("Game", "").strip())
        except ValueError:
            return None
        game_logs = (playoff_sections_state.get("sections") or {}).get("_game_logs", []) or []
        for game in game_logs:
            if game.get("game_num") != game_num:
                continue
            for snap_team in game.get("teams", []) or []:
                if snap_team.get("name") != team.name:
                    continue
                for snap_player in snap_team.get("players", []) or []:
                    if snap_player.get("name") == player_stat_key(team, player):
                        quarter = player_card_quarter_var.get()
                        if quarter != "All":
                            if quarter == "OT":
                                q = 5
                            else:
                                try:
                                    q = int(quarter.replace("Q", ""))
                                except ValueError:
                                    q = 0
                            q_rows = [dict(row) for row in snap_player.get("quarter_stats", []) or [] if row.get("period", 0) >= q] if quarter == "OT" else [dict(row) for row in snap_player.get("quarter_stats", []) or [] if row.get("period") == q]
                            if q_rows:
                                merged = {"minutes": 0, "pts": 0, "reb": 0, "ast": 0, "stl": 0, "blk": 0, "tov": 0, "oreb": 0, "dreb": 0, "pf": 0, "fgm": 0, "fga": 0, "tpm": 0, "tpa": 0, "ftm": 0, "fta": 0, "plus_minus": 0, "shot_diet": {}, "defended_diet": {}}
                                for q_row in q_rows:
                                    for key in tuple(k for k in merged if k not in ("shot_diet", "defended_diet")):
                                        merged[key] += q_row.get(key, 0)
                                    for diet_key in ("shot_diet", "defended_diet"):
                                        for k, v in (q_row.get(diet_key, {}) or {}).items():
                                            merged[diet_key][k] = merged[diet_key].get(k, 0) + v
                                return merged
                            return {"minutes": 0, "pts": 0, "reb": 0, "ast": 0, "stl": 0, "blk": 0, "tov": 0, "oreb": 0, "dreb": 0, "pf": 0, "fgm": 0, "fga": 0, "tpm": 0, "tpa": 0, "ftm": 0, "fta": 0, "plus_minus": 0, "shot_diet": {}, "defended_diet": {}}
                        return {
                            "minutes": snap_player.get("minutes", 0), "pts": snap_player.get("pts", 0),
                            "reb": snap_player.get("reb", 0), "ast": snap_player.get("ast", 0),
                            "stl": snap_player.get("stl", 0), "blk": snap_player.get("blk", 0),
                            "tov": snap_player.get("tov", 0), "oreb": snap_player.get("oreb", 0),
                            "dreb": snap_player.get("dreb", 0), "pf": snap_player.get("pf", 0),
                            "fgm": snap_player.get("fgm", 0), "fga": snap_player.get("fga", 0),
                            "tpm": snap_player.get("tpm", 0), "tpa": snap_player.get("tpa", 0),
                            "ftm": snap_player.get("ftm", 0), "fta": snap_player.get("fta", 0),
                            "plus_minus": snap_player.get("plus_minus", 0),
                            "shot_diet": dict(snap_player.get("shot_diet", {}) or {}),
                            "defended_diet": dict(snap_player.get("defended_diet", {}) or {}),
                        }
        return None

    def player_card_selected_row(team: Team, player: Player) -> Dict[str, float]:
        snapshot_row = player_card_game_snapshot_row(team, player)
        if snapshot_row is not None:
            return snapshot_row
        quarter = player_card_quarter_var.get()
        if quarter == "All":
            return {
                "minutes": player.minutes, "pts": player.pts, "reb": player.reb, "ast": player.ast,
                "stl": player.stl, "blk": player.blk_stat, "tov": player.tov, "oreb": player.oreb_stat,
                "dreb": player.dreb_stat, "pf": player.pf, "fgm": player.fgm, "fga": player.fga,
                "tpm": player.tpm, "tpa": player.tpa, "ftm": player.ftm, "fta": player.fta,
                "plus_minus": player.plus_minus,
                "shot_diet": dict(getattr(player, "shot_diet", {}) or {}),
                "defended_diet": dict(getattr(player, "defended_diet", {}) or {}),
            }
        if quarter == "OT":
            completed = [r for r in (getattr(team, "quarter_player_stats", {}) or {}).get(player_stat_key(team, player), []) if r.get("period", 0) >= 5]
            if SIM_CONTEXT.get("period", 0) >= 5:
                completed.append(live_quarter_player_row(team, player))
            if completed:
                row = {"minutes": 0, "pts": 0, "reb": 0, "ast": 0, "stl": 0, "blk": 0, "tov": 0, "oreb": 0, "dreb": 0, "pf": 0, "fgm": 0, "fga": 0, "tpm": 0, "tpa": 0, "ftm": 0, "fta": 0, "plus_minus": 0, "shot_diet": {}, "defended_diet": {}}
                for q_row in completed:
                    for key in tuple(k for k in row if k not in ("shot_diet", "defended_diet")):
                        row[key] += q_row.get(key, 0)
                    for diet_key in ("shot_diet", "defended_diet"):
                        for k, v in (q_row.get(diet_key, {}) or {}).items():
                            row[diet_key][k] = row[diet_key].get(k, 0) + v
                return row
            q = 5
        else:
            try:
                q = int(quarter.replace("Q", ""))
            except ValueError:
                q = 1
        row = next((r for r in (getattr(team, "quarter_player_stats", {}) or {}).get(player_stat_key(team, player), []) if r.get("period") == q), None)
        if row is None and SIM_CONTEXT.get("period") == q:
            row = live_quarter_player_row(team, player)
        return row or {
            "minutes": 0, "pts": 0, "reb": 0, "ast": 0, "stl": 0, "blk": 0, "tov": 0,
            "oreb": 0, "dreb": 0, "pf": 0, "fgm": 0, "fga": 0, "tpm": 0, "tpa": 0,
            "ftm": 0, "fta": 0, "plus_minus": 0, "shot_diet": {}, "defended_diet": {},
        }

    def player_card_rating_value(row: Dict[str, float]) -> float:
        positive = (
            row.get("pts", 0)
            + 1.2 * row.get("reb", 0)
            + 1.5 * row.get("ast", 0)
            + 2.0 * row.get("stl", 0)
            + 2.0 * row.get("blk", 0)
            + 0.5 * row.get("plus_minus", 0)
        )
        negative = row.get("tov", 0) + 0.35 * max(0, row.get("fga", 0) - row.get("fgm", 0))
        return max(0.0, min(9.9, (positive - negative) / 5.0))

    def player_card_quarter_rows(team: Team, player: Player) -> List[Tuple[str, Dict[str, float]]]:
        rows = []
        for q in range(1, 5):
            row = next((r for r in (getattr(team, "quarter_player_stats", {}) or {}).get(player_stat_key(team, player), []) if r.get("period") == q), None)
            if row is None and SIM_CONTEXT.get("period") == q:
                row = live_quarter_player_row(team, player)
            rows.append((f"Q{q}", row or {"pts": 0, "reb": 0, "ast": 0, "stl": 0, "blk": 0, "tov": 0, "fgm": 0, "fga": 0, "plus_minus": 0}))
        ot_row = player_card_selected_row(team, player) if player_card_quarter_var.get() == "OT" else None
        if ot_row is None:
            ot_completed = [r for r in (getattr(team, "quarter_player_stats", {}) or {}).get(player_stat_key(team, player), []) if r.get("period", 0) >= 5]
            if SIM_CONTEXT.get("period", 0) >= 5:
                ot_completed.append(live_quarter_player_row(team, player))
            if ot_completed:
                ot_row = {"pts": 0, "reb": 0, "ast": 0, "stl": 0, "blk": 0, "tov": 0, "fgm": 0, "fga": 0, "plus_minus": 0}
                for q_row in ot_completed:
                    for key in ot_row:
                        ot_row[key] += q_row.get(key, 0)
        rows.append(("OT", ot_row or {"pts": 0, "reb": 0, "ast": 0, "stl": 0, "blk": 0, "tov": 0, "fgm": 0, "fga": 0, "plus_minus": 0}))
        return rows

    def draw_card_headshot(canvas, player: Player | None, size: int = 92):
        canvas.delete("all")
        w = int(canvas.cget("width"))
        h = int(canvas.cget("height"))
        cx, cy = w / 2, h / 2
        canvas.create_oval(cx - size / 2, cy - size / 2, cx + size / 2, cy + size / 2, fill="#06283d", outline="#0ea5e9", width=2)
        if player is None:
            canvas.create_text(cx, cy, text="?", fill=TEXT, font=("Segoe UI", 18, "bold"))
            return
        image = load_player_headshot(player)
        if image is not None:
            canvas.create_image(cx, cy, image=image)
            canvas.image = image
        else:
            canvas.create_text(cx, cy, text=player_initials(player.name), fill=TEXT, font=("Segoe UI", 16, "bold"))

    def set_player_card_quarter_buttons():
        active = player_card_quarter_var.get()
        for label, btn in player_card_quarter_buttons.items():
            is_active = label == active
            btn.configure(
                fg="#ffffff",
                bg="#9ca3af" if is_active else "#4b5563",
                activebackground="#b6b6b6",
                activeforeground="#ffffff",
            )

    def draw_player_card_rating_bars(team: Team, player: Player):
        player_card_rating_canvas.delete("all")
        w = max(340, player_card_rating_canvas.winfo_width())
        h = max(140, player_card_rating_canvas.winfo_height())
        rows = player_card_quarter_rows(team, player)
        max_val = max(1.0, max(player_card_rating_value(row) for _label, row in rows))
        bar_w = (w - 50) / max(1, len(rows))
        for idx, (label, row) in enumerate(rows):
            value = player_card_rating_value(row)
            x0 = 18 + idx * bar_w
            x1 = x0 + bar_w - 20
            bar_h = 18 + (h - 58) * (value / max_val)
            y1 = h - 24
            y0 = y1 - bar_h
            player_card_rating_canvas.create_rectangle(x0, y0, x1, y1, fill="#9ca3af", outline="", width=0)
            player_card_rating_canvas.create_text((x0 + x1) / 2, y0 - 12, text=f"{value:.1f}", fill=TEXT, font=("Segoe UI", 10, "bold"))
            player_card_rating_canvas.create_text((x0 + x1) / 2, h - 8, text=label, fill=TEXT_SOFT, font=("Segoe UI", 10, "bold"))

    def player_card_diet_value(diet: Dict, key: str) -> int:
        try:
            return max(0, int(round(float(diet.get(key, 0) or 0))))
        except (TypeError, ValueError):
            return 0

    def player_card_set_diet_value(diet: Dict, key: str, value: int):
        diet[key] = max(0, int(value))

    def player_card_reduce_diet_keys(diet: Dict, keys: Tuple[str, ...], amount: int):
        remaining = max(0, int(amount))
        for key in keys:
            if remaining <= 0:
                break
            current = player_card_diet_value(diet, key)
            take = min(current, remaining)
            player_card_set_diet_value(diet, key, current - take)
            remaining -= take

    def player_card_add_makes_with_capacity(diet: Dict, keys: Tuple[str, ...], amount: int):
        remaining = max(0, int(amount))
        for key in keys:
            if remaining <= 0:
                break
            attempts = player_card_diet_value(diet, key)
            made_key = f"{key}_made"
            made = player_card_diet_value(diet, made_key)
            add = min(max(0, attempts - made), remaining)
            player_card_set_diet_value(diet, made_key, made + add)
            remaining -= add

    def normalize_player_card_shot_diet(row: Dict[str, float], raw_diet: Dict[str, int]) -> Dict[str, int]:
        """
        Player cards need non-overlapping zones. Raw diet also stores context tags
        like ISO/C&S/open/contested, so normalize a display copy to the stat row.
        """
        diet = dict(raw_diet or {})
        fga = max(0, int(round(float(row.get("fga", 0) or 0))))
        fgm = max(0, int(round(float(row.get("fgm", 0) or 0))))

        zone_keys = ("three", "mid", "rim", "post")
        quality_keys = ("wide_open", "contested")

        if fga <= 0:
            for key in zone_keys + ("dunk",) + quality_keys:
                player_card_set_diet_value(diet, key, 0)
                player_card_set_diet_value(diet, f"{key}_made", 0)
            return diet

        # Dunks are a finish at the rim on the card. Putbacks usually already
        # have a rim/dunk shot type, so they remain a context tag only.
        rim_attempts = player_card_diet_value(diet, "rim") + player_card_diet_value(diet, "dunk")
        rim_makes = player_card_diet_value(diet, "rim_made") + player_card_diet_value(diet, "dunk_made")
        player_card_set_diet_value(diet, "rim", rim_attempts)
        player_card_set_diet_value(diet, "rim_made", rim_makes)
        player_card_set_diet_value(diet, "dunk", 0)
        player_card_set_diet_value(diet, "dunk_made", 0)

        zone_attempts = sum(player_card_diet_value(diet, key) for key in zone_keys)
        if zone_attempts < fga:
            player_card_set_diet_value(diet, "rim", player_card_diet_value(diet, "rim") + fga - zone_attempts)
        elif zone_attempts > fga:
            player_card_reduce_diet_keys(diet, ("rim", "post", "mid", "three"), zone_attempts - fga)

        for key in zone_keys:
            made_key = f"{key}_made"
            player_card_set_diet_value(diet, made_key, min(player_card_diet_value(diet, made_key), player_card_diet_value(diet, key)))
        zone_makes = sum(player_card_diet_value(diet, f"{key}_made") for key in zone_keys)
        if zone_makes < fgm:
            player_card_add_makes_with_capacity(diet, ("rim", "three", "mid", "post"), fgm - zone_makes)
        elif zone_makes > fgm:
            player_card_reduce_diet_keys(diet, ("rim_made", "post_made", "mid_made", "three_made"), zone_makes - fgm)

        quality_attempts = sum(player_card_diet_value(diet, key) for key in quality_keys)
        if quality_attempts < fga:
            player_card_set_diet_value(diet, "contested", player_card_diet_value(diet, "contested") + fga - quality_attempts)
        elif quality_attempts > fga:
            player_card_reduce_diet_keys(diet, ("contested", "wide_open"), quality_attempts - fga)

        for key in quality_keys:
            made_key = f"{key}_made"
            player_card_set_diet_value(diet, made_key, min(player_card_diet_value(diet, made_key), player_card_diet_value(diet, key)))
        quality_makes = sum(player_card_diet_value(diet, f"{key}_made") for key in quality_keys)
        if quality_makes < fgm:
            player_card_add_makes_with_capacity(diet, ("contested", "wide_open"), fgm - quality_makes)
        elif quality_makes > fgm:
            player_card_reduce_diet_keys(diet, ("contested_made", "wide_open_made"), quality_makes - fgm)

        return diet

    def compact_player_card_diet(title: str, diet: Dict[str, int], defended: bool = False, row: Dict[str, float] | None = None) -> str:
        if defended:
            return (
                f"{title}\n"
                f"3P {format_diet_pair_compact(diet, 'three')}   MID {format_diet_pair_compact(diet, 'mid')}\n"
                f"RIM {format_diet_group_compact(diet, ('rim', 'dunk'))}   POST {format_diet_pair_compact(diet, 'post')}\n"
                f"OPEN {format_diet_pair_compact(diet, 'wide_open')}   TOV {diet.get('turnover', 0)}\n"
                f"TOTAL {diet_total_text(diet)}"
            )
        display_diet = normalize_player_card_shot_diet(row or {}, diet)
        zone_total = diet_total_for_keys(display_diet, ("three", "mid", "rim", "post"))
        return (
            f"{title}\n"
            f"3P {format_diet_pair_compact(display_diet, 'three')}   MID {format_diet_pair_compact(display_diet, 'mid')}\n"
            f"RIM {format_diet_pair_compact(display_diet, 'rim')}   POST {format_diet_pair_compact(display_diet, 'post')}\n"
            f"OPEN {format_diet_pair_compact(display_diet, 'wide_open')}   CONT {format_diet_pair_compact(display_diet, 'contested')}\n"
            f"TOTAL {zone_total}   ISO {format_diet_pair_compact(display_diet, 'iso')}   C&S {format_diet_pair_compact(display_diet, 'catch_shoot')}"
        )

    def update_player_card_strip(team: Team, selected: Player | None):
        players = sorted(team.roster, key=lambda p: (p.pts, p.fga, p.minutes, overall_rating(p)), reverse=True)[:8]
        for idx, btn in enumerate(player_card_strip_buttons):
            if idx >= len(players):
                btn.configure(text="-", command=lambda: None, fg="#020617", bg="#9ca3af", activebackground="#b6b6b6", activeforeground="#020617")
                continue
            p = players[idx]
            label = table_player_name(p.name, 12)
            is_selected = p is selected
            btn.configure(
                text=label,
                fg="#020617" if is_selected else "#f8fafc",
                bg="#9ca3af" if is_selected else "#4b5563",
                activebackground="#b6b6b6",
                activeforeground="#020617",
                command=lambda player_name=p.name: (player_card_player_var.set(player_name), update_player_card_widget()),
            )

    def player_card_play_title(line: str) -> str:
        lower = line.lower()
        if "dunk" in lower or "slams" in lower or "throws down" in lower:
            return "Dunk"
        if "three" in lower or "from deep" in lower or "downtown" in lower:
            return "Three"
        if "block" in lower or "swats" in lower or "rejects" in lower:
            return "Block"
        if "steal" in lower or "strips" in lower:
            return "Steal"
        if "free throw" in lower or "line" in lower:
            return "Free throws"
        if "putback" in lower:
            return "Putback"
        return line[:42] + ("..." if len(line) > 42 else "")

    def find_player_by_name(name: str) -> Player | None:
        for team in (SIM_CONTEXT.get("teamA"), SIM_CONTEXT.get("teamB")):
            if team is None:
                continue
            player = next((p for p in team.roster if p.name == name), None)
            if player is not None:
                return player
        return None

    def draw_card_event_headshot(canvas, player_name: str, fallback_player: Player | None):
        event_player = find_player_by_name(player_name)
        if event_player is not None:
            draw_card_headshot(canvas, event_player, size=46)
            return
        canvas.delete("all")
        w = int(canvas.cget("width"))
        h = int(canvas.cget("height"))
        cx, cy = w / 2, h / 2
        canvas.create_oval(cx - 23, cy - 23, cx + 23, cy + 23, fill="#06283d", outline="#0ea5e9", width=2)
        canvas.create_text(cx, cy, text=player_initials(player_name or getattr(fallback_player, "name", "")), fill=TEXT, font=("Segoe UI", 11, "bold"))

    def rebuild_player_card_play_rows(events: List[Dict], fallback_player: Player):
        for row, _canvas, _title_var, _meta_var, _score_var in player_card_play_rows:
            row.destroy()
        player_card_play_rows.clear()
        body_width = max(620, player_card_plays_body.winfo_width() or player_card_content.winfo_width() or 760)
        title_wrap = max(360, body_width - 230)
        for idx, event in enumerate(events):
            row = tk.Frame(player_card_plays_body, bg="#050505", padx=10, pady=8, highlightthickness=1, highlightbackground="#1f2937")
            row.pack(fill="x", pady=(0, 6))
            row.columnconfigure(1, weight=1)
            row.columnconfigure(2, minsize=112)
            canvas = tk.Canvas(row, width=50, height=50, bg="#050505", highlightthickness=0)
            canvas.grid(row=0, column=0, rowspan=2, sticky="nw", padx=(0, 10))
            title_var = tk.StringVar(value="-")
            meta_var = tk.StringVar(value="")
            score_var = tk.StringVar(value="")
            tk.Label(row, textvariable=meta_var, bg="#050505", fg=TEXT_SOFT, font=("Segoe UI", 9, "bold"), anchor="w").grid(row=0, column=1, sticky="ew")
            tk.Label(row, textvariable=title_var, bg="#050505", fg=TEXT, font=("Segoe UI", 14, "bold"), anchor="w", wraplength=title_wrap, justify="left").grid(row=1, column=1, sticky="ew")
            tk.Label(row, textvariable=score_var, bg="#050505", fg=TEXT_SOFT, font=("Segoe UI", 11, "bold"), anchor="e", width=13).grid(row=0, column=2, rowspan=2, sticky="ne")
            event_player_name = event.get("player", "") or getattr(fallback_player, "name", "")
            draw_card_event_headshot(canvas, event_player_name, fallback_player)
            meta_var.set(f"{event.get('type', 'PLAY')}  |  {event.get('team') or short_team_name(active_player_card_team())}")
            title_var.set(event.get("title") or player_card_play_title(event.get("line", "")))
            score_var.set(event.get("score", ""))
            player_card_play_rows.append((row, canvas, title_var, meta_var, score_var))

    def update_player_card_plays(team: Team, player: Player):
        show_all = player_card_show_all_plays.get()
        player_card_view_all_btn.configure(text="Player only" if show_all else "View all")
        source = list(reversed(player_card_play_events))
        quarter = player_card_quarter_var.get()
        if quarter != "All":
            prefix = "Q5" if quarter == "OT" else quarter
            if quarter == "OT":
                source = [event for event in source if str(event.get("score", "")).startswith(("Q5", "Q6", "Q7", "Q8"))]
            else:
                source = [event for event in source if str(event.get("score", "")).startswith(prefix)]
        if show_all:
            filtered = source[:24]
        else:
            filtered = [
                event for event in source
                if player.name == event.get("player")
            ][:12]
        if not filtered:
            filtered = [{
                "player": player.name,
                "players": [player.name],
                "type": "WAITING",
                "title": f"{player.name} has no tracked plays yet. Makes, misses, assists, blocks, and steals will show here live.",
                "line": "",
                "score": "",
            }]
        rebuild_player_card_play_rows(filtered, player)

    def restore_player_card_scroll(position: float):
        try:
            player_card_scroll_canvas.after_idle(lambda pos=position: player_card_scroll_canvas.yview_moveto(pos))
        except Exception:
            pass

    def update_player_card_widget(_event=None):
        try:
            selected_tab = str(series_tabs.tab(series_tabs.select(), "text"))
        except Exception:
            selected_tab = ""
        try:
            current_scroll = player_card_scroll_canvas.yview()[0]
        except Exception:
            current_scroll = 0.0
        sync_player_card_dropdown()
        signature = (
            player_card_team_var.get(),
            player_card_player_var.get(),
            player_card_game_var.get(),
            player_card_quarter_var.get(),
            bool(player_card_show_all_plays.get()),
        )
        preserve_scroll = selected_tab == "Cards" and getattr(update_player_card_widget, "_last_signature", None) == signature
        update_player_card_widget._last_signature = signature
        team = active_player_card_team()
        player = None
        if team is not None:
            player = player_from_stat_key(team, player_card_player_var.get())
        if player is None:
            draw_card_headshot(player_card_canvas, None)
            player_card_name_var.set("Start a game")
            player_card_team_line_var.set("Pick a team and player to load the card.")
            player_card_big_line_var.set("")
            player_card_score_line_var.set("")
            player_card_social_var.set("")
            for var in player_card_stat_vars.values():
                var.set("-")
            player_card_shot_diet_var.set("Shot Diet\n0/0")
            player_card_def_diet_var.set("Defended\n0/0")
            player_card_rating_canvas.delete("all")
            for row, _canvas, title_var, meta_var, score_var in player_card_play_rows:
                row.pack_forget()
                title_var.set("-")
                meta_var.set("")
                score_var.set("")
            if preserve_scroll:
                restore_player_card_scroll(current_scroll)
            return
        draw_card_headshot(player_card_canvas, player)
        set_player_card_quarter_buttons()
        update_player_card_strip(team, player)
        row = player_card_selected_row(team, player)
        fgm = row.get("fgm", 0)
        fga = row.get("fga", 0)
        tpm = row.get("tpm", 0)
        tpa = row.get("tpa", 0)
        ftm = row.get("ftm", 0)
        fta = row.get("fta", 0)
        pts = row.get("pts", 0)
        # TS% is calibrated around a 2-point "standard" shot (2 * TSA makes
        # a 100%-efficient 2-point shooter read as 100). 1-on-1 scores 1s
        # and 2s instead of 2s/3s, so the standard shot there is worth 1,
        # not 2 -- use that scale or every 1-on-1 card reads as ~50% TS
        # even on a flawless shooting night.
        ts_scale = 1 if mode_var.get() == "1-on-1" else 2
        ts_denom = ts_scale * (fga + 0.44 * fta)
        ts = 0.0 if ts_denom == 0 else 100 * pts / ts_denom
        badge_line = format_player_badges(player)
        diet = row.get("shot_diet") if isinstance(row.get("shot_diet"), dict) else (getattr(player, "shot_diet", {}) or {})
        defended = row.get("defended_diet") if isinstance(row.get("defended_diet"), dict) else (getattr(player, "defended_diet", {}) or {})
        player_card_name_var.set(player.name)
        player_card_team_line_var.set(f"{short_team_name(team)} · {gui_player_position(player)} · {plan_label(getattr(player, 'archetype', 'balanced'))}")
        player_card_big_line_var.set(f"{int(pts)} pts  {int(row.get('reb', 0))} reb  {int(row.get('ast', 0))} ast")
        opponent = SIM_CONTEXT.get("teamB") if team is SIM_CONTEXT.get("teamA") else SIM_CONTEXT.get("teamA")
        player_card_score_line_var.set(f"{team.score}-{opponent.score if opponent else 0}" if opponent else "")
        player_card_social_var.set(f"Badges: {badge_line}")
        values = {
            "MIN": f"{row.get('minutes', 0) / 60:.1f}",
            "PTS": f"{int(pts)}",
            "REB": f"{int(row.get('reb', 0))}",
            "AST": f"{int(row.get('ast', 0))}",
            "STL": f"{int(row.get('stl', 0))}",
            "BLK": f"{int(row.get('blk', 0))}",
            "+/-": f"{int(row.get('plus_minus', 0)):+d}",
            "FG%": f"{safe_pct(fgm, fga):.1f}",
            "FG": f"{int(fgm)}/{int(fga)}",
            "3FG": f"{int(tpm)}/{int(tpa)}",
            "FTS": f"{int(ftm)}/{int(fta)}",
            "TO": f"{int(row.get('tov', 0))}",
            "PF": f"{int(row.get('pf', 0))}",
            "OREB": f"{int(row.get('oreb', 0))}",
            "DREB": f"{int(row.get('dreb', 0))}",
            "TS%": f"{ts:.1f}",
        }
        for key, var in player_card_stat_vars.items():
            var.set(values.get(key, "-"))
        player_card_shot_diet_var.set(compact_player_card_diet("Shot Diet", diet, row=row))
        player_card_def_diet_var.set(compact_player_card_diet("Defended Diet", defended, defended=True))
        if preserve_scroll:
            restore_player_card_scroll(current_scroll)

    def update_commentator_widget():
        teams = [SIM_CONTEXT.get("teamA"), SIM_CONTEXT.get("teamB")]
        if not all(teams):
            set_text_widget(commentator_text, "Game recap feed will fill once a game starts. It tracks player of the game, turning points, runs, clutch context, and series memory.")
            return

        period = SIM_CONTEXT.get("period", 1)
        period_time = SIM_CONTEXT.get("period_time", 0)
        team_a, team_b = teams
        all_players = team_a.roster + team_b.roster
        player_of_game = max(
            all_players,
            key=lambda p: p.pts + 1.15 * p.reb + 1.45 * p.ast + 3 * p.stl + 3 * p.blk_stat - 2 * p.tov + 0.35 * p.plus_minus
        )
        top_scorers = sorted(all_players, key=lambda p: (p.pts, p.fgm, -p.fga), reverse=True)[:4]
        best_run_team = team_a if getattr(team_a, "biggest_run", 0) >= getattr(team_b, "biggest_run", 0) else team_b
        possession = SIM_CONTEXT.get("possession")

        lines = [
            "LIVE GAME RECAP",
            "=" * 72,
            f"Score: {team_a.name} {team_a.score} - {team_b.score} {team_b.name}",
            f"Clock: Q{period} {format_time(period_time) if isinstance(period_time, int) else '-'} | Possession: {getattr(possession, 'name', '-')}",
            "",
            f"Player of the game right now: {player_of_game.name} - {player_of_game.pts} PTS, {player_of_game.reb} REB, {player_of_game.ast} AST, +/- {player_of_game.plus_minus:+d}.",
            "Top scoring table: " + " | ".join(f"{p.name} {p.pts} ({p.fgm}/{p.fga})" for p in top_scorers),
            f"Biggest run: {best_run_team.name} with a {getattr(best_run_team, 'biggest_run', 0)}-0 burst.",
        ]

        turning_points = [getattr(t, "last_turning_point", None) for t in teams if getattr(t, "last_turning_point", None)]
        if turning_points:
            lines.append(f"Turning point watch: {turning_points[-1]}")

        if series_game_results:
            lines.extend(["", "Series lookback:"])
            lines.extend(f"  {row}" for row in series_game_results[-4:])

        lines.append("")
        lines.append("Team profile:")
        for team in teams:
            opponent = team_b if team is team_a else team_a
            totals = accumulate_team_totals(team)
            diet = getattr(team, "shot_diet", {}) or {}
            paint = diet.get("rim", 0) + diet.get("dunk", 0) + diet.get("post", 0)
            threes = diet.get("three", 0)
            clutch = max(team.on_floor or team.roster, key=lambda p: p.clutchness * 1.4 + p.usage + p.shot_tendency)
            hot = [p for p in team.roster if p.fga >= 6 and safe_pct(p.fgm, p.fga) >= 55]
            cold = [p for p in team.roster if p.fga >= 6 and safe_pct(p.fgm, p.fga) <= 30]

            lines.append(
                f"  {team.name}: FG {totals.get('fgm', 0)}/{totals.get('fga', 0)}, "
                f"3P {totals.get('tpm', 0)}/{totals.get('tpa', 0)}, paint attacks {paint}, "
                f"3PA diet {threes}, TOV {totals.get('tov', 0)}."
            )
            lines.append(f"    Pressure option: {clutch.name}. Coach should be thinking about him if this tightens late.")
            if hot:
                p = max(hot, key=lambda x: x.pts)
                lines.append(f"    Hot hand: {p.name} is {p.fgm}/{p.fga}; the defense has to account for every touch.")
            if cold:
                p = max(cold, key=lambda x: x.fga)
                lines.append(f"    Cold watch: {p.name} is {p.fgm}/{p.fga}; those are possessions to manage.")
            if period >= 4 and period_time <= 6 * 60 and abs(team.score - opponent.score) <= 10:
                lines.append("    Late-game note: close window is open, so star touches and timeout discipline matter now.")

        if top_play_lines:
            lines.extend(["", "Recent top play:", f"  {top_play_lines[-1]}"])
        set_text_widget(commentator_text, "\n".join(lines))

