    def assigned_on_court_slots(players: List[Player], team: Team = None) -> List[Tuple[str, Player]]:
        if team is not None and getattr(team, "lock_custom_starting_positions", False):
            return [(str(getattr(player, "position", "SF") or "SF").upper(), player) for player in players[:5]]
        ordered = balanced_lineup_order(players)
        return [(slot, player) for slot, player in zip(("PG", "SG", "SF", "PF", "C"), ordered)]

    def player_live_values(slot: str, player: Player) -> Tuple:
        name = player.name
        if len(name) > 22:
            name = name[:21] + "."
        fg = f"{player.fgm}/{player.fga}"
        tp = f"{player.tpm}/{player.tpa}"
        ft = f"{player.ftm}/{player.fta}"
        fg_pct = f"{safe_pct(player.fgm, player.fga):.1f}"
        tp_pct = f"{safe_pct(player.tpm, player.tpa):.1f}"
        ft_pct = f"{safe_pct(player.ftm, player.fta):.1f}"
        mins = f"{player.minutes / 60:.1f}"
        return (slot, name, mins, player.pts, player.reb, player.ast, player.stl, player.blk_stat, player.oreb_stat, player.tov, player.pf, fg, fg_pct, tp, tp_pct, ft, ft_pct)

    def update_on_court_boxscore():
        team_a = SIM_CONTEXT.get("teamA")
        team_b = SIM_CONTEXT.get("teamB")
        rows = []
        if team_a is None or team_b is None:
            rows.append((("", "Start a game to see the 10 players currently on the floor.", "", "", "", "", "", "", "", "", "", "", "", "", "", "", ""), ()))
            team_stats = (None, None)
        else:
            for team in (team_a, team_b):
                rows.append((("", team.name, "", "", "", "", "", "", "", "", "", "", "", "", "", "", ""), ("team",)))
                for slot, player in assigned_on_court_slots(getattr(team, "on_floor", [])[:5], team):
                    rows.append((player_live_values(slot, player), ()))
            team_stats = (team_stats_values(team_a), team_stats_values(team_b))

        signature = (tuple((tuple(values), tuple(tags)) for values, tags in rows), team_stats)
        if getattr(update_on_court_boxscore, "_last_signature", None) == signature:
            return
        update_on_court_boxscore._last_signature = signature

        children = list(on_court_box.get_children())
        for index, (values, tags) in enumerate(rows):
            if index < len(children):
                item = children[index]
                if tuple(on_court_box.item(item, "values")) != tuple(str(v) for v in values) or tuple(on_court_box.item(item, "tags")) != tuple(tags):
                    on_court_box.item(item, values=values, tags=tags)
            else:
                on_court_box.insert("", "end", values=values, tags=tags)
        for item in children[len(rows):]:
            on_court_box.delete(item)

        if team_a is None or team_b is None:
            update_team_stats_box(None, None)
        else:
            update_team_stats_box(team_a, team_b)

    def team_stats_values(team: Team) -> Tuple:
        totals = accumulate_team_totals(team)
        fg = f"{totals['fgm']}/{totals['fga']}"
        tp = f"{totals['tpm']}/{totals['tpa']}"
        ft = f"{totals['ftm']}/{totals['fta']}"
        fg_pct = f"{safe_pct(totals['fgm'], totals['fga']):.1f}"
        tp_pct = f"{safe_pct(totals['tpm'], totals['tpa']):.1f}"
        ft_pct = f"{safe_pct(totals['ftm'], totals['fta']):.1f}"
        name = team.name
        if len(name) > 20:
            name = table_player_name(name, 20)
        return (
            name,
            team.score,
            totals["reb"],
            totals["oreb"],
            totals["dreb"],
            totals["ast"],
            totals["stl"],
            totals["blk"],
            totals["tov"],
            fg,
            fg_pct,
            tp,
            tp_pct,
            ft,
            ft_pct,
        )

    def update_team_stats_box(team_a: Team | None, team_b: Team | None):
        teams = (team_a, team_b)
        for row, team in enumerate(teams):
            values = ("", "", "", "", "", "", "", "", "", "", "", "", "", "", "") if team is None else team_stats_values(team)
            for label, value in zip(team_stats_labels[row], values):
                label.configure(text=value)

