    def update_scoreboard(data):
        if data.get("season_progress"):
            completed = int(data.get("completed", 0))
            total = max(1, int(data.get("total", 1)))
            pct = completed / total * 100
            period_clock_var.set("SEASON")
            scoreboard_status_var.set(f"Season sim: {completed}/{total} games ({pct:.1f}%)")
            return
        if data.get("reset_series_score"):
            team_a_series_var.set("(0-0)")
            team_b_series_var.set("(0-0)")
            scoreboard_status_var.set(data.get("series_status", "Ready for next series"))
            return
        if "game_result" in data:
            series_game_results.append(data["game_result"])
            update_live_dashboard()
            return
        if "series_status" in data:
            scoreboard_status_var.set(data["series_status"])
            if {"series_team_a", "series_wins_a", "series_team_b", "series_wins_b"}.issubset(data):
                series_team_a = data["series_team_a"]
                series_team_b = data["series_team_b"]
                wins_a = data["series_wins_a"]
                wins_b = data["series_wins_b"]
                current_a = team_a_name_var.get()
                current_b = team_b_name_var.get()
                if current_a == series_team_a and current_b == series_team_b:
                    team_a_series_var.set(f"({wins_a}-{wins_b})")
                    team_b_series_var.set(f"({wins_b}-{wins_a})")
                elif current_a == series_team_b and current_b == series_team_a:
                    team_a_series_var.set(f"({wins_b}-{wins_a})")
                    team_b_series_var.set(f"({wins_a}-{wins_b})")
            return
        teams_changed = team_a_name_var.get() != data["team_a"] or team_b_name_var.get() != data["team_b"]
        team_a_name_var.set(data["team_a"])
        team_b_name_var.set(data["team_b"])
        team_a_score_var.set(data["score_a"])
