    def gui_fantasy_picker(pools: Dict[str, List[Tuple[Player, str]]], taken_names: set):
        def stat_value(player: Player, key: str):
            if key == "name":
                return player.name
            if key == "team":
                return getattr(player, "source_team", "")
            if key == "pos":
                return player.position
            if key == "ovr":
                return fantasy_ovr(player)
            if key == "play":
                return round(player.playmaking * 100)
            if key == "three":
                return round(player.three_rating * 100)
            if key == "mid":
                return round(player.mid_rating * 100)
            if key == "rim":
                return round(player.rim_rating * 100)
            if key == "pdef":
                return round(player.perimeter_def * 100)
            if key == "idef":
                return round(player.interior_def * 100)
            if key == "stl":
                return round(player.steal * 100)
            if key == "blk":
                return round(player.block * 100)
            if key == "arch":
                return plan_label(getattr(player, "archetype", "balanced"))
            return ""

        def open_dialog(result_queue):
            dialog = tk.Toplevel(root)
            dialog.title("Fantasy Draft Board")
            dialog.configure(bg=APP_BG)
            dialog.geometry("1180x720")
            dialog.minsize(980, 600)
            dialog.transient(root)
            dialog.grab_set()
            dialog.columnconfigure(0, weight=1)
            dialog.rowconfigure(2, weight=1)
            dialog.rowconfigure(4, weight=0)

            header = tk.Frame(dialog, bg=PANEL, highlightthickness=1, highlightbackground=BORDER_BRIGHT, padx=14, pady=10)
            header.grid(row=0, column=0, sticky="ew", padx=14, pady=(14, 8))
            header.columnconfigure(1, weight=1)
            tk.Label(header, text="Fantasy Draft Board", bg=PANEL, fg=GOLD, font=("Segoe UI", 18, "bold")).grid(row=0, column=0, sticky="w")
            status_var_dialog = tk.StringVar(value="Pick a player, choose a version if needed, then draft.")
            tk.Label(header, textvariable=status_var_dialog, bg=PANEL, fg=TEXT_SOFT, font=("Segoe UI", 11), anchor="e").grid(row=0, column=1, sticky="ew")

            filters = ttk.Frame(dialog)
            filters.grid(row=1, column=0, sticky="ew", padx=14, pady=(0, 8))
            filters.columnconfigure(3, weight=1)
            tk.Label(filters, text="Position", bg=APP_BG, fg=TEXT_SOFT, font=("Segoe UI", 11, "bold")).grid(row=0, column=0, padx=(0, 6))
            pos_var = tk.StringVar(value="All")
            pos_dropdown = ttk.Combobox(filters, textvariable=pos_var, values=("All", "PG", "SG", "SF", "PF", "C"), state="readonly", width=10)
            pos_dropdown.grid(row=0, column=1, padx=(0, 14))
            tk.Label(filters, text="Search", bg=APP_BG, fg=TEXT_SOFT, font=("Segoe UI", 11, "bold")).grid(row=0, column=2, padx=(0, 6))
            search_var = tk.StringVar(value="")
            search_entry = dark_entry(filters, textvariable=search_var)
            search_entry.grid(row=0, column=3, sticky="ew")

            board_frame = tk.Frame(dialog, bg=CARD, highlightthickness=1, highlightbackground=BORDER)
            board_frame.grid(row=2, column=0, sticky="nsew", padx=14, pady=(0, 10))
            board_frame.columnconfigure(0, weight=1)
            board_frame.rowconfigure(0, weight=1)
            columns = ("name", "team", "pos", "ovr", "play", "three", "mid", "rim", "pdef", "idef", "stl", "blk", "arch")
            tree = ttk.Treeview(board_frame, columns=columns, show="headings", height=15, style="Series.Treeview")
            y_scroll = ttk.Scrollbar(board_frame, orient="vertical", command=tree.yview)
            tree.configure(yscrollcommand=y_scroll.set)
            widths = {
                "name": 170, "team": 230, "pos": 48, "ovr": 52, "play": 56, "three": 56,
                "mid": 56, "rim": 56, "pdef": 58, "idef": 58, "stl": 52, "blk": 52, "arch": 150,
            }
            labels = {
                "name": "Player", "team": "Team", "pos": "POS", "ovr": "OVR", "play": "PLAY",
                "three": "3PT", "mid": "MID", "rim": "RIM", "pdef": "PDEF", "idef": "IDEF",
                "stl": "STL", "blk": "BLK", "arch": "Archetype",
            }
            for col in columns:
                tree.heading(col, text=labels[col])
                tree.column(col, width=widths[col], anchor="center" if col not in ("name", "team", "arch") else "w", stretch=col in ("name", "team", "arch"))
            tree.grid(row=0, column=0, sticky="nsew", padx=(8, 0), pady=8)
            y_scroll.grid(row=0, column=1, sticky="ns", pady=8)

            version_frame = tk.Frame(dialog, bg=CARD, highlightthickness=1, highlightbackground=BORDER, padx=8, pady=8)
            version_frame.grid(row=3, column=0, sticky="ew", padx=14, pady=(0, 10))
            version_frame.columnconfigure(0, weight=1)
            tk.Label(version_frame, text="Versions", bg=CARD, fg=GOLD, font=("Segoe UI", 12, "bold"), anchor="w").grid(row=0, column=0, sticky="ew")
            version_tree = ttk.Treeview(version_frame, columns=("team", "pos", "ovr", "play", "three", "mid", "rim", "pdef", "idef", "arch"), show="headings", height=4, style="Series.Treeview")
            for col, label, width in (
                ("team", "Team", 260), ("pos", "POS", 46), ("ovr", "OVR", 52), ("play", "PLAY", 56),
                ("three", "3PT", 56), ("mid", "MID", 56), ("rim", "RIM", 56), ("pdef", "PDEF", 58),
                ("idef", "IDEF", 58), ("arch", "Archetype", 160),
            ):
                version_tree.heading(col, text=label)
                version_tree.column(col, width=width, anchor="center" if col not in ("team", "arch") else "w", stretch=col in ("team", "arch"))
            version_tree.grid(row=1, column=0, sticky="ew", pady=(6, 0))

            selected_candidates = []
            selected_versions = []

            def filtered_candidates():
                pos = pos_var.get()
                query = search_var.get().strip().lower()
                if pos == "All":
                    base = available_all_fantasy_players(pools, taken_names)
                else:
                    base = available_fantasy_pool(pools.get(pos, []), taken_names)
                if query:
                    base = [
                        (player, desc)
                        for player, desc in base
                        if query in player.name.lower() or query in getattr(player, "source_team", "").lower()
                    ]
                return base

            def refresh_board(*_args):
                selected_candidates.clear()
                tree.delete(*tree.get_children())
                for idx, (player, _desc) in enumerate(filtered_candidates(), start=0):
                    selected_candidates.append(player)
                    tree.insert("", "end", iid=str(idx), values=tuple(stat_value(player, col) for col in columns))
                status_var_dialog.set(f"{len(selected_candidates)} available players shown. Taken players are hidden.")
                version_tree.delete(*version_tree.get_children())
                selected_versions.clear()

            def refresh_versions(_event=None):
                version_tree.delete(*version_tree.get_children())
                selected_versions.clear()
                selection = tree.selection()
                if not selection:
                    return
                candidate = selected_candidates[int(selection[0])]
                versions = list(getattr(candidate, "fantasy_versions", [candidate]))
                versions.sort(key=fantasy_ovr, reverse=True)
                for idx, version in enumerate(versions):
                    selected_versions.append(version)
                    version_tree.insert(
                        "",
                        "end",
                        iid=str(idx),
                        values=(
                            getattr(version, "source_team", ""),
                            version.position,
                            fantasy_ovr(version),
                            round(version.playmaking * 100),
                            round(version.three_rating * 100),
                            round(version.mid_rating * 100),
                            round(version.rim_rating * 100),
                            round(version.perimeter_def * 100),
                            round(version.interior_def * 100),
                            plan_label(getattr(version, "archetype", "balanced")),
                        ),
                    )
                if selected_versions:
                    version_tree.selection_set("0")
                    version_tree.focus("0")

            def chosen_player():
                version_selection = version_tree.selection()
                if version_selection and selected_versions:
                    return selected_versions[int(version_selection[0])]
                selection = tree.selection()
                if selection:
                    candidate = selected_candidates[int(selection[0])]
                    versions = list(getattr(candidate, "fantasy_versions", [candidate]))
                    versions.sort(key=fantasy_ovr, reverse=True)
                    return versions[0]
                return None

            def draft_selected():
                player = chosen_player()
                if player is None:
                    status_var_dialog.set("Select a player first.")
                    return
                result_queue.put(player)
                dialog.destroy()

            def cancel():
                result_queue.put(None)
                dialog.destroy()

            button_frame = ttk.Frame(dialog)
            button_frame.grid(row=4, column=0, sticky="ew", padx=14, pady=(0, 14))
            button_frame.columnconfigure(0, weight=1)
            button_frame.columnconfigure(1, weight=1)
            ttk.Button(button_frame, text="Draft Selected Player", command=draft_selected).grid(row=0, column=0, sticky="ew", padx=(0, 6))
            ttk.Button(button_frame, text="Cancel", command=cancel).grid(row=0, column=1, sticky="ew", padx=(6, 0))

            tree.bind("<<TreeviewSelect>>", refresh_versions)
            tree.bind("<Double-Button-1>", lambda _event: draft_selected())
            version_tree.bind("<Double-Button-1>", lambda _event: draft_selected())
            pos_dropdown.bind("<<ComboboxSelected>>", refresh_board)
            search_var.trace_add("write", refresh_board)
            dialog.protocol("WM_DELETE_WINDOW", cancel)
            refresh_board()
            search_entry.focus_set()

        return gui_dialog_wait(open_dialog)

    def gui_select_custom_playoff_teams() -> List[str]:
        def open_dialog(result_queue):
            dialog = tk.Toplevel(root)
            dialog.title("Choose 16 Playoff Teams")
            dialog.configure(bg=APP_BG)
            dialog.geometry("900x620")
            dialog.minsize(760, 520)
            dialog.transient(root)
            dialog.grab_set()
            dialog.columnconfigure(0, weight=1)
            dialog.columnconfigure(2, weight=1)
            dialog.rowconfigure(1, weight=1)

            picker_title = "Full Playoffs" if mode_var.get() == "Full playoffs" else "Custom 16-Team Playoffs"
            title_var = tk.StringVar(value="Choose exactly 16 teams from every team currently in the sim. Order matters: 1 vs 16, 2 vs 15, etc.")
            tk.Label(dialog, text=picker_title, bg=APP_BG, fg=GOLD, font=("Segoe UI", 18, "bold")).grid(row=0, column=0, columnspan=3, sticky="ew", padx=16, pady=(14, 2))
            tk.Label(dialog, textvariable=title_var, bg=APP_BG, fg=TEXT_SOFT, font=("Segoe UI", 11)).grid(row=1, column=0, columnspan=3, sticky="new", padx=16, pady=(0, 10))

            available_frame = tk.Frame(dialog, bg=CARD, highlightthickness=1, highlightbackground=BORDER, padx=8, pady=8)
            available_frame.grid(row=2, column=0, sticky="nsew", padx=(16, 8), pady=(32, 10))
            available_frame.columnconfigure(0, weight=1)
            available_frame.rowconfigure(1, weight=1)
            tk.Label(available_frame, text="Available Teams", bg=CARD, fg=GOLD, font=("Segoe UI", 12, "bold")).grid(row=0, column=0, sticky="w")
            available_list = tk.Listbox(available_frame, bg=PANEL_DARK, fg=TEXT, selectbackground=BLUE, selectforeground="#ffffff", relief="flat", font=("Segoe UI", 11), activestyle="none")
            available_scroll = ttk.Scrollbar(available_frame, orient="vertical", command=available_list.yview)
            available_list.configure(yscrollcommand=available_scroll.set)
            available_list.grid(row=1, column=0, sticky="nsew", pady=(6, 0))
            available_scroll.grid(row=1, column=1, sticky="ns", pady=(6, 0))

            selected_frame = tk.Frame(dialog, bg=CARD, highlightthickness=1, highlightbackground=BORDER, padx=8, pady=8)
            selected_frame.grid(row=2, column=2, sticky="nsew", padx=(8, 16), pady=(32, 10))
            selected_frame.columnconfigure(0, weight=1)
            selected_frame.rowconfigure(1, weight=1)
            selected_label_var = tk.StringVar(value="Selected Teams (0/16)")
            tk.Label(selected_frame, textvariable=selected_label_var, bg=CARD, fg=GOLD, font=("Segoe UI", 12, "bold")).grid(row=0, column=0, sticky="w")
            selected_list = tk.Listbox(selected_frame, bg=PANEL_DARK, fg=TEXT, selectbackground=BLUE, selectforeground="#ffffff", relief="flat", font=("Segoe UI", 11), activestyle="none")
            selected_scroll = ttk.Scrollbar(selected_frame, orient="vertical", command=selected_list.yview)
            selected_list.configure(yscrollcommand=selected_scroll.set)
            selected_list.grid(row=1, column=0, sticky="nsew", pady=(6, 0))
            selected_scroll.grid(row=1, column=1, sticky="ns", pady=(6, 0))

            selected_names = []

            def refresh_lists():
                available_list.delete(0, "end")
                for name in team_names:
                    if name not in selected_names:
                        available_list.insert("end", name)
                selected_list.delete(0, "end")
                for idx, name in enumerate(selected_names, start=1):
                    selected_list.insert("end", f"{idx}. {name}")
                selected_label_var.set(f"Selected Teams ({len(selected_names)}/16)")
                title_var.set("Choose exactly 16 teams from every team currently in the sim. Order matters: 1 vs 16, 2 vs 15, etc.")

            def selected_raw_name() -> str | None:
                selection = selected_list.curselection()
                if not selection:
                    return None
                idx = selection[0]
                if 0 <= idx < len(selected_names):
                    return selected_names[idx]
                return None

            def add_team():
                selection = available_list.curselection()
                if not selection:
                    return
                name = available_list.get(selection[0])
                if len(selected_names) >= 16:
                    title_var.set("You already have 16 teams. Remove one before adding another.")
                    return
                selected_names.append(name)
                refresh_lists()

            def remove_team():
                name = selected_raw_name()
                if name and name in selected_names:
                    selected_names.remove(name)
                    refresh_lists()

            def move_selected(delta: int):
                name = selected_raw_name()
                if not name:
                    return
                idx = selected_names.index(name)
                new_idx = max(0, min(len(selected_names) - 1, idx + delta))
                if idx == new_idx:
                    return
                selected_names.pop(idx)
                selected_names.insert(new_idx, name)
                refresh_lists()
                selected_list.selection_set(new_idx)

            def is_excluded_from_autofill(name: str) -> bool:
                return (
                    is_olympic_team_name(name)
                    or "Dream Team" in name
                    or "Redeem Team" in name
                )

            def team_strength(name: str) -> float:
                try:
                    team = factories[name]()
                except Exception:
                    return 0.0
                roster = team.roster[:8] or team.roster
                if not roster:
                    return 0.0
                return sum(overall_rating(p) for p in roster) / len(roster)

            def auto_fill():
                candidates = [
                    name for name in team_names
                    if name not in selected_names and not is_excluded_from_autofill(name)
                ]
                candidates.sort(key=team_strength, reverse=True)
                for name in candidates:
                    if len(selected_names) >= 16:
                        break
                    selected_names.append(name)
                refresh_lists()

            def start():
                if len(selected_names) != 16:
                    title_var.set(f"Need exactly 16 teams. You currently have {len(selected_names)}.")
                    return
                result_queue.put(list(selected_names))
                dialog.destroy()

            def cancel():
                result_queue.put([])
                dialog.destroy()

            button_frame = ttk.Frame(dialog)
            button_frame.grid(row=2, column=1, sticky="ns", pady=(32, 10))
            ttk.Button(button_frame, text="Add >", command=add_team).pack(fill="x", pady=(0, 8))
            ttk.Button(button_frame, text="< Remove", command=remove_team).pack(fill="x", pady=(0, 16))
            ttk.Button(button_frame, text="Move Up", command=lambda: move_selected(-1)).pack(fill="x", pady=(0, 8))
            ttk.Button(button_frame, text="Move Down", command=lambda: move_selected(1)).pack(fill="x", pady=(0, 16))
            ttk.Button(button_frame, text="Fill Top 16", command=auto_fill).pack(fill="x")

            footer_buttons = ttk.Frame(dialog)
            footer_buttons.grid(row=3, column=0, columnspan=3, sticky="ew", padx=16, pady=(0, 16))
            footer_buttons.columnconfigure(0, weight=1)
            footer_buttons.columnconfigure(1, weight=1)
            ttk.Button(footer_buttons, text="Start Playoffs", command=start).grid(row=0, column=0, sticky="ew", padx=(0, 6))
            ttk.Button(footer_buttons, text="Cancel", command=cancel).grid(row=0, column=1, sticky="ew", padx=(6, 0))
            available_list.bind("<Double-Button-1>", lambda _event: add_team())
            selected_list.bind("<Double-Button-1>", lambda _event: remove_team())
            dialog.protocol("WM_DELETE_WINDOW", cancel)
            refresh_lists()

        return gui_dialog_wait(open_dialog)

