        dialog.transient(root)

        pools_cache = {"players": None}
        selected_incoming = {"player": None}

        top = ttk.Frame(dialog, padding=10)
        top.pack(fill="x")
        ttk.Label(top, text="Team").grid(row=0, column=0, padx=(0, 8), sticky="w")
