        minutes_var = tk.StringVar(value="")
        minutes_entry = dark_entry(top, textvariable=minutes_var, width=8)
        minutes_entry.grid(row=4, column=1, padx=(0, 14), pady=(8, 0), sticky="w")
        ttk.Label(top, text="Optional -- pin this swapped-in player to an exact target minutes/game instead of letting the sim decide.", foreground=MUTED).grid(row=4, column=2, pady=(8, 0), sticky="w")
        ttk.Label(top, textvariable=status_line, foreground=GOLD).grid(row=5, column=0, columnspan=3, pady=(8, 0), sticky="w")
        top.columnconfigure(1, weight=1)
        top.columnconfigure(2, weight=1)

        body = ttk.Frame(dialog, padding=(10, 0, 10, 10))
        body.pack(fill="both", expand=True)
        body.columnconfigure(0, weight=1)
        body.columnconfigure(1, weight=1)
        body.rowconfigure(1, weight=1)

        ttk.Label(body, text="Current Team Slot").grid(row=0, column=0, sticky="w", pady=(0, 4))
        ttk.Label(body, text="All-Time Fantasy Pool").grid(row=0, column=1, sticky="w", pady=(0, 4))

        left_frame = tk.Frame(body, bg=PANEL, highlightbackground=BORDER, highlightthickness=1)
        left_frame.grid(row=1, column=0, sticky="nsew", padx=(0, 8))
        right_frame = tk.Frame(body, bg=PANEL, highlightbackground=BORDER, highlightthickness=1)
        right_frame.grid(row=1, column=1, sticky="nsew", padx=(8, 0))
        left_frame.rowconfigure(0, weight=1)
        left_frame.columnconfigure(0, weight=1)
        right_frame.rowconfigure(1, weight=1)
        right_frame.columnconfigure(0, weight=1)

        outgoing_list = tk.Listbox(left_frame, bg=PANEL_DARK, fg=TEXT, selectbackground=BLUE, selectforeground="#ffffff", font=("Segoe UI", 12), activestyle="none", exportselection=False)
        outgoing_scroll = ttk.Scrollbar(left_frame, orient="vertical", command=outgoing_list.yview)
        outgoing_list.configure(yscrollcommand=outgoing_scroll.set)
        outgoing_list.grid(row=0, column=0, sticky="nsew")
        outgoing_scroll.grid(row=0, column=1, sticky="ns")

        search_var = tk.StringVar(value="")
        search = dark_entry(right_frame, textvariable=search_var)
        search.grid(row=0, column=0, columnspan=2, sticky="ew", padx=8, pady=(8, 6))
        incoming_list = tk.Listbox(right_frame, bg=PANEL_DARK, fg=TEXT, selectbackground=BLUE, selectforeground="#ffffff", font=("Segoe UI", 12), activestyle="none", exportselection=False)
        incoming_scroll = ttk.Scrollbar(right_frame, orient="vertical", command=incoming_list.yview)
        incoming_list.configure(yscrollcommand=incoming_scroll.set)
        incoming_list.grid(row=1, column=0, sticky="nsew", padx=(8, 0), pady=(0, 8))
        incoming_scroll.grid(row=1, column=1, sticky="ns", padx=(0, 8), pady=(0, 8))
        swap_preview = tk.Text(body, height=5, bg="#05070f", fg=TEXT, insertbackground=TEXT, relief="flat", wrap="word", font=("Segoe UI", 11), padx=10, pady=8)
        swap_preview.grid(row=2, column=0, columnspan=2, sticky="ew", pady=(10, 0))
        swap_preview.configure(state="disabled")

        outgoing_names = []
        incoming_players = []
        version_players = []
        outgoing_label_to_name = {}
        incoming_label_to_player = {}

        def set_swap_preview(player: Player | None):
            swap_preview.configure(state="normal")
            swap_preview.delete("1.0", "end")
            swap_preview.insert("end", fantasy_player_preview_text(player))
            swap_preview.configure(state="disabled")

        def all_swap_players():
            if pools_cache["players"] is None:
                pools = build_fantasy_player_pools(None)
                pool_players = [player for player, _desc in available_all_fantasy_players(pools, set())]
                pool_players.sort(key=fantasy_ovr, reverse=True)
                pools_cache["players"] = pool_players
            return pools_cache["players"]

        def refresh_outgoing():
            outgoing_list.delete(0, "end")
            outgoing_names.clear()
            outgoing_label_to_name.clear()
            team_name = swap_team_var.get()
            try:
                base_team = factories[team_name]()
                swaps = gui_roster_swaps.get(team_name, {})
                labels = []
                for idx, player in enumerate(base_team.roster, start=1):
                    outgoing_names.append(player.name)
                    incoming = swaps.get(player.name)
                    if incoming is not None:
                        minutes_override = getattr(incoming, "gui_target_minutes_override", None)
                        minutes_note = f" @ {minutes_override} min" if minutes_override is not None else ""
                        label = f"{idx}. {player.name} -> {incoming.name} ({getattr(incoming, 'source_team', 'All-Time')}){minutes_note}"
                    else:
                        label = f"{idx}. {player.name} ({player.position})"
                    labels.append(label)
                    outgoing_label_to_name[label] = player.name
                    outgoing_list.insert("end", label)
                outgoing_box.configure(values=labels)
                if labels:
                    outgoing_select_var.set(labels[0])
                    outgoing_list.selection_clear(0, "end")
                    outgoing_list.selection_set(0)
                    outgoing_list.activate(0)
                    outgoing_list.see(0)
                else:
                    outgoing_select_var.set("")
                status_line.set(f"Loaded {len(outgoing_names)} roster slots for {team_name}. {roster_swap_summary()}")
            except Exception as exc:
                outgoing_box.configure(values=[])
                outgoing_select_var.set("")
                status_line.set(f"Could not load roster for {team_name}: {exc}")
                output_queue.put(f"\n[GUI] Roster swap roster load error for {team_name}: {exc}\n")

        def set_incoming_player(player):
            versions = list(getattr(player, "fantasy_versions", []) or [])
            if not versions:
                versions = [player]
            versions.sort(key=fantasy_ovr, reverse=True)
            version_players.clear()
            version_players.extend(versions)
            labels = [f"{p.name} | {getattr(p, 'source_team', 'All-Time')} | {p.position} | OVR {fantasy_ovr(p)}" for p in versions]
            version_box.configure(values=labels)
            version_var.set(labels[0] if labels else "")
            selected_incoming["player"] = versions[0] if versions else player
            set_swap_preview(selected_incoming["player"])

        def refresh_incoming(*_args):
            incoming_list.delete(0, "end")
            incoming_players.clear()
            incoming_label_to_player.clear()
            try:
                term = search_var.get().strip().lower()
                players = all_swap_players()
                if term:
                    players = [p for p in players if term in p.name.lower() or term in getattr(p, "source_team", "").lower()]
                labels = []
                for player in players[:250]:
                    incoming_players.append(player)
                    source = getattr(player, "source_team", "All-Time")
                    label = f"{player.name} | OVR {fantasy_ovr(player)} | {source}"
                    labels.append(label)
                    incoming_label_to_player[label] = player
                    incoming_list.insert("end", f"{player.name:<24} OVR {fantasy_ovr(player):>2} | {source}")
                incoming_box.configure(values=labels)
                if incoming_players:
                    incoming_select_var.set(labels[0])
                    incoming_list.selection_clear(0, "end")
                    incoming_list.selection_set(0)
                    incoming_list.activate(0)
                    incoming_list.see(0)
                    set_incoming_player(incoming_players[0])
                    status_line.set(f"Loaded {len(incoming_players)} all-time players shown. {roster_swap_summary()}")
                else:
                    incoming_select_var.set("")
                    version_box.configure(values=[])
                    version_var.set("")
                    selected_incoming["player"] = None
                    set_swap_preview(None)
                    status_line.set("No all-time players match that search.")
            except Exception as exc:
                incoming_box.configure(values=[])
                incoming_select_var.set("")
                set_swap_preview(None)
                status_line.set(f"Could not load all-time pool: {exc}")
                output_queue.put(f"\n[GUI] Roster swap all-time pool load error: {exc}\n")

        def select_incoming(_event=None):
            selection = incoming_list.curselection()
            if not selection:
                return
            set_incoming_player(incoming_players[selection[0]])

        def select_incoming_from_dropdown(_event=None):
            player = incoming_label_to_player.get(incoming_select_var.get())
            if player is not None:
                set_incoming_player(player)

        def select_version(_event=None):
            if not version_players:
                return
            try:
                idx = list(version_box.cget("values")).index(version_var.get())
            except ValueError:
                idx = 0
            if 0 <= idx < len(version_players):
                selected_incoming["player"] = version_players[idx]
                set_swap_preview(selected_incoming["player"])

        def selected_outgoing_name():
            label_name = outgoing_label_to_name.get(outgoing_select_var.get())
            if label_name:
                return label_name
            selection = outgoing_list.curselection()
            if not selection:
                return None
            idx = selection[0]
            return outgoing_names[idx] if 0 <= idx < len(outgoing_names) else None

        def apply_swap():
            team_name = swap_team_var.get()
            outgoing_name = selected_outgoing_name()
            incoming = selected_incoming.get("player")
            if not team_name or not outgoing_name or incoming is None:
                status_line.set("Pick both an outgoing player and an incoming player.")
                return
            minutes_text = minutes_var.get().strip()
            minutes_override = None
            if minutes_text:
                try:
                    minutes_override = int(round(float(minutes_text)))
                except ValueError:
                    status_line.set("Minutes must be a number (or leave it blank to let the sim decide).")
                    return
                if not (0 <= minutes_override <= 48):
                    status_line.set("Minutes must be between 0 and 48.")
                    return
            # Store our own clone rather than the shared fantasy-pool object --
            # the override is per-swap, and other swaps/dialogs reuse that
            # same pooled Player instance.
            import copy
            incoming_for_swap = copy.deepcopy(incoming)
            incoming_for_swap.gui_target_minutes_override = minutes_override
            gui_roster_swaps.setdefault(team_name, {})[outgoing_name] = incoming_for_swap
            source = getattr(incoming, "source_team", "All-Time")
            minutes_note = f" and pinned to {minutes_override} min/game" if minutes_override is not None else ""
            status_line.set(f"{team_name}: {outgoing_name} will be replaced by {incoming.name} ({source}){minutes_note}.")
            status_var.set(roster_swap_summary())
            minutes_var.set("")
            refresh_outgoing()

        def remove_swap():
            team_name = swap_team_var.get()
            outgoing_name = selected_outgoing_name()
            if outgoing_name and team_name in gui_roster_swaps:
                gui_roster_swaps[team_name].pop(outgoing_name, None)
                if not gui_roster_swaps[team_name]:
                    gui_roster_swaps.pop(team_name, None)
            status_line.set(roster_swap_summary())
            status_var.set(roster_swap_summary())
