        def all_player_similarity_pool() -> List[Player]:
            try:
                pools = build_fantasy_player_pools(None)
                players = [player for player, _desc in available_all_fantasy_players(pools, set())]
            except Exception:
                players = []
            return players

        def player_similarity_score(a: Player, b: Player) -> float:
            weighted_fields = (
                ("three_rating", 1.20), ("mid_rating", 0.95), ("rim_rating", 1.05), ("dunk_rating", 0.80),
                ("playmaking", 1.05), ("ball_handle", 0.95), ("perimeter_def", 0.85), ("interior_def", 0.85),
                ("oreb", 0.45), ("dreb", 0.55), ("speed", 0.65), ("shot_iq", 0.80),
                ("three_tendency", 0.50), ("drive_tendency", 0.45), ("post_tendency", 0.45), ("iso_tendency", 0.60),
            )
            total = 0.0
            for field_name, weight in weighted_fields:
                total += abs(getattr(a, field_name, 0.50) - getattr(b, field_name, 0.50)) * weight
            total += abs((getattr(a, "height", 78) or 78) - (getattr(b, "height", 78) or 78)) / 60.0
            if str(getattr(a, "position", "")) != str(getattr(b, "position", "")):
                total += 0.18
            return total

        def shades_of(player: Player) -> str:
            matches = []
            for candidate in all_player_similarity_pool():
                if candidate.name == player.name and getattr(candidate, "source_team", "") == "Custom Player":
                    continue
                matches.append((player_similarity_score(player, candidate), candidate))
            matches.sort(key=lambda item: item[0])
            labels = []
            seen = set()
            for _score, candidate in matches:
                key = candidate.name
                if key in seen:
                    continue
                seen.add(key)
                labels.append(f"{candidate.name} ({getattr(candidate, 'source_team', 'All-Time')})")
                if len(labels) == 3:
                    break
            return ", ".join(labels) if labels else "None"

