    sim_engine.GUI_OPTION_PICKER = gui_option_picker

    def run_selected_sim():
        mode = mode_var.get()
        original_stdout = sys.stdout
        original_input = builtins.input
        original_gui_series_queue = sim_engine.GUI_SERIES_UPDATE_QUEUE
        original_gui_scoreboard_queue = sim_engine.GUI_SCOREBOARD_QUEUE
        original_sleep_scale = sim_engine.SIM_SLEEP_SCALE
        original_fantasy_picker = sim_engine.GUI_FANTASY_PICKER
        original_position_picker = sim_engine.GUI_POSITION_PICKER
        original_option_picker = sim_engine.GUI_OPTION_PICKER
        proxy = GuiOutputProxy(output_queue, scoreboard_queue, original_stdout, section_queue)

        def gui_input(prompt=""):
            if prompt:
                output_queue.put(prompt)
            output_queue.put("\n[GUI] Waiting for input. Type below and press Send, or press Continue for blank.\n")
            input_continue_event.clear()
            while True:
                try:
                    response = gui_input_queue.get(timeout=0.1)
                    break
                except queue.Empty:
                    if input_continue_event.is_set():
                        response = ""
                        break
            output_queue.put(f"[GUI] Input: {response if response else '<blank>'}\n")
            return response

        sys.stdout = proxy
        builtins.input = gui_input
        sim_engine.GUI_SERIES_UPDATE_QUEUE = section_queue if mode in ("Playoff series", "Custom 16-team playoffs", "Full playoffs", "Olympic tournament") else None
        sim_engine.GUI_SCOREBOARD_QUEUE = scoreboard_queue
        sim_engine.SIM_FAST_FORWARD = False
        sim_engine.SIM_JUMP_TARGET = None
        sim_engine.SIM_PAUSED = False
        apply_gui_speed()
        original_ruleset = CURRENT_RULESET
        set_ruleset("FIBA" if mode == "Olympic tournament" else rules_var.get())
        sim_factories = active_team_factories()
        sim_completed = False
        sim_error = None
        try:
            if mode == "Game":
                team_a = sim_factories[team_a_var.get()]()
                team_b = sim_factories[team_b_var.get()]()
                apply_star_clutchness(team_a, team_b)
                assign_player_badges(team_a)
                assign_player_badges(team_b)
                simulate_game(team_a, team_b)
            elif mode == "1-on-1":
                team_name_a, player_name_a = picked_1v1["team_a"], picked_1v1["player_a"]
                team_name_b, player_name_b = picked_1v1["team_b"], picked_1v1["player_b"]
                if not team_name_a or not team_name_b:
                    print("Pick two players for 1-on-1.")
                else:
                    roster_a = sim_factories[team_name_a]().roster
                    roster_b = sim_factories[team_name_b]().roster
                    player_a = next((p for p in roster_a if p.name == player_name_a), None)
                    player_b = next((p for p in roster_b if p.name == player_name_b), None)
                    if player_a is None or player_b is None:
                        print("Could not find one of the selected players.")
                    else:
                        assign_player_badges(Team("temp", [player_a]))
                        assign_player_badges(Team("temp", [player_b]))
                        simulate_1v1_game(player_a, player_b)
            elif mode == "Playoff series":
                run_best_of_7_series(sim_factories[team_a_var.get()], sim_factories[team_b_var.get()])
            elif mode in ("Custom 16-team playoffs", "Full playoffs"):
                selected = gui_select_custom_playoff_teams()
                if len(selected) == 16:
                    run_custom_16_team_playoffs(selected, sim_factories)
                else:
                    print("Full playoffs cancelled." if mode == "Full playoffs" else "Custom playoffs cancelled.")
            elif mode == "Season mode":
                selected = gui_select_season_teams()
                if len(selected) == 30:
                    status_var.set("Season sim running...")
                    scoreboard_status_var.set("Season sim running in background...")
                    with contextlib.redirect_stdout(io.StringIO()):
                        run_quiet_82_game_season(selected, sim_factories, section_queue, scoreboard_queue)
                    scoreboard_status_var.set("Season complete. Open standings, averages, advanced, shots/defense, or awards.")
                else:
                    print("Season mode cancelled.")
            elif mode == "Fantasy draft season":
                run_fantasy_draft_and_game(None)
            elif mode == "2026 fantasy draft season":
                run_fantasy_draft_and_game("2026 ")
            elif mode == "Fantasy draft playoffs":
                run_fantasy_draft_playoffs()
            elif mode == "Olympic tournament":
                run_olympic_tournament(sim_factories)
            else:
                run_2016_playoffs()
            sim_completed = True
        except Exception:
            sim_error = traceback.format_exc()
            print(sim_error)
        finally:
            sim_engine.SIM_FAST_FORWARD = False
            sim_engine.SIM_JUMP_TARGET = None
            sim_engine.SIM_PAUSED = False
            sim_engine.SIM_SLEEP_SCALE = original_sleep_scale
            set_ruleset(original_ruleset)
            sim_engine.GUI_FANTASY_PICKER = original_fantasy_picker
            sim_engine.GUI_POSITION_PICKER = original_position_picker
            sim_engine.GUI_OPTION_PICKER = original_option_picker
            sim_engine.GUI_SERIES_UPDATE_QUEUE = original_gui_series_queue
            sim_engine.GUI_SCOREBOARD_QUEUE = original_gui_scoreboard_queue
            builtins.input = original_input
            sys.stdout = original_stdout
            running["active"] = False
            if mode in ("Playoff series", "Custom 16-team playoffs", "Full playoffs", "Full 2016 playoffs", "Fantasy draft playoffs", "Olympic tournament"):
                scoreboard_queue.put({"reset_series_score": True, "series_status": "Series reset: 0-0"})
            if sim_completed:
                pass
            else:
                output_queue.put("\n[GUI] Simulation stopped because of an error. Check the traceback above.\n")
                if sim_error:
                    status_var.set("Error")

    def start_sim():
        if running["active"]:
            return
        mode = mode_var.get()
        if mode == "1-on-1":
            if not picked_1v1["team_a"] or not picked_1v1["team_b"]:
                status_var.set("Use Play 1-on-1 to pick two players first.")
                return
        elif mode not in ("Full 2016 playoffs", "Custom 16-team playoffs", "Full playoffs", "Season mode", "Fantasy draft season", "2026 fantasy draft season", "Fantasy draft playoffs", "Olympic tournament") and team_a_var.get() == team_b_var.get():
            status_var.set("Pick two different teams.")
            return
        clear_log()
        running["active"] = True
        pause_button.configure(text="Pause")
        status_var.set("Running...")
        if mode == "1-on-1":
            set_scoreboard_teams(picked_1v1["player_a"], picked_1v1["player_b"])
        else:
            set_scoreboard_teams(team_a_var.get(), team_b_var.get())
        scoreboard_status_var.set("Starting simulation...")
        thread = threading.Thread(target=run_selected_sim, daemon=True)
        thread.start()

    def send_gui_input():
        value = gui_input_var.get()
        gui_input_var.set("")
        gui_input_queue.put(value)
        input_continue_event.set()

    def gui_fast_sim(label: str, target: str | None):
        if not running["active"]:
            status_var.set("Start a simulation first.")
            return
        sim_engine.SIM_FAST_FORWARD = True
        sim_engine.SIM_JUMP_TARGET = target
        status_var.set(label)
        output_queue.put(f"\n[GUI] {label}\n")

    def toggle_pause():
        if not running["active"]:
            status_var.set("Start a simulation first.")
            return
        sim_engine.SIM_PAUSED = not sim_engine.SIM_PAUSED
        pause_button.configure(text="Resume" if sim_engine.SIM_PAUSED else "Pause")
        status_var.set("Paused" if sim_engine.SIM_PAUSED else "Running...")
        output_queue.put("\n[GUI] Simulation paused.\n" if sim_engine.SIM_PAUSED else "\n[GUI] Simulation resumed.\n")

    def active_adjustment_team() -> Team | None:
        possession = SIM_CONTEXT.get("possession")
        if possession is not None:
            return possession
        return SIM_CONTEXT.get("teamA")

    def queue_gui_timeout():
        team = active_adjustment_team()
