    def queue_gui_subs():
        team = active_adjustment_team()
        if team is None:
            adjustment_status_var.set("No active team yet.")
            return
        team.manual_sub_request = True
        adjustment_status_var.set(f"Manual substitutions queued for {short_team_name(team)} at the next dead ball.")
        output_queue.put(f"\n[GUI] Manual substitution menu queued for {team.name}.\n")

    def cycle_gui_offense():
        team = active_adjustment_team()
        if team is None:
            adjustment_status_var.set("No active team yet.")
            return
        options = ("balanced", "five_out", "four_out_one_in", "three_out_two_in", "post_heavy", "motion", "star_spread")
        current = OFFENSIVE_SET_OVERRIDES.get(team.name, getattr(team, "game_plan", {}).get("offense", "balanced"))
        next_code = options[(options.index(current) + 1) % len(options)] if current in options else options[0]
        OFFENSIVE_SET_OVERRIDES[team.name] = next_code
        apply_offensive_set_override(team)
        adjustment_status_var.set(f"{short_team_name(team)} offense: {plan_label(next_code)}")
        output_queue.put(f"\n[GUI] {team.name} offense changed to {plan_label(next_code)}.\n")
        update_adjustment_status()

    def cycle_gui_defense():
        team = active_adjustment_team()
        if team is None:
            adjustment_status_var.set("No active team yet.")
            return
        options = ("standard", "switch", "drop", "show_recover", "blitz", "stay_home", "top_lock", "pack_paint", "wall_paint", "zone", "load_star")
        current = DEFENSIVE_SCHEME_OVERRIDES.get(team.name, getattr(team, "game_plan", {}).get("defense", "standard"))
        next_code = options[(options.index(current) + 1) % len(options)] if current in options else options[0]
        DEFENSIVE_SCHEME_OVERRIDES[team.name] = next_code
        apply_defensive_scheme_override(team)
        adjustment_status_var.set(f"{short_team_name(team)} defense: {plan_label(next_code)}")
        output_queue.put(f"\n[GUI] {team.name} defense changed to {plan_label(next_code)}.\n")
        update_adjustment_status()

    def matchup_note():
        team = active_adjustment_team()
        if team is None:
            adjustment_status_var.set("No active team yet.")
            return
        opponent = SIM_CONTEXT.get("teamB") if team is SIM_CONTEXT.get("teamA") else SIM_CONTEXT.get("teamA")
        if opponent is None:
            return
        target = max(opponent.on_floor, key=lambda p: p.pts + p.usage * 20 + p.shot_tendency * 10)
        team.defensive_focus = target.name
        adjustment_status_var.set(f"{short_team_name(team)} loading help toward {target.name}.")
        output_queue.put(f"\n[GUI] {team.name} defensive focus set to {target.name}.\n")
        update_adjustment_status()

    gui_refresh_state = {
        "live_at": 0.0,
        "heavy_at": 0.0,
        "finish_refreshed": False,
        "live_dirty": True,
        "heavy_dirty": True,
    }

    def refresh_live_widgets(include_heavy: bool = False):
        update_on_court_boxscore()
        update_scoreboard_extras()
        if include_heavy:
            update_extra_gui_tabs()
            set_adjustments_tab_visibility()

    def poll_queues():
        # A single unhandled exception anywhere below used to stop this
        # function from ever rescheduling itself (root.after was the very
        # last line), which permanently froze the play log, scoreboard, and
        # box score for the rest of the session. Guarantee the reschedule no
        # matter what happens above it.
        try:
            lines_processed = 0
            try:
                while lines_processed < 80:
                    append_log(output_queue.get_nowait())
                    lines_processed += 1
            except queue.Empty:
                pass
            # Drain bursts and paint only the newest state. Repainting every
            # stale queued possession made the live table appear to stutter
            # or reload.
            latest_scoreboard = None
            try:
                while True:
                    latest_scoreboard = scoreboard_queue.get_nowait()
            except queue.Empty:
                pass
            if latest_scoreboard is not None:
                update_scoreboard(latest_scoreboard)
                gui_refresh_state["live_dirty"] = True
            try:
                while True:
                    update_series_boxes(section_queue.get_nowait())
                    gui_refresh_state["heavy_dirty"] = True
            except queue.Empty:
                pass
            if not running["active"] and status_var.get() == "Running...":
                status_var.set("Finished")
                pause_button.configure(text="Pause")
            elif not running["active"] and str(pause_button.cget("text")) != "Pause":
                pause_button.configure(text="Pause")
            now = time.monotonic()
            if running["active"] and not sim_engine.SIM_PAUSED:
                gui_refresh_state["finish_refreshed"] = False
                if gui_refresh_state["live_dirty"] and now - gui_refresh_state["live_at"] >= 0.15:
                    refresh_live_widgets(include_heavy=False)
                    gui_refresh_state["live_at"] = now
                    gui_refresh_state["live_dirty"] = False
                if gui_refresh_state["heavy_dirty"] and now - gui_refresh_state["heavy_at"] >= 1.50:
                    update_extra_gui_tabs()
                    gui_refresh_state["heavy_at"] = now
                    gui_refresh_state["heavy_dirty"] = False
            elif status_var.get() == "Finished" and not gui_refresh_state["finish_refreshed"]:
                refresh_live_widgets(include_heavy=True)
                gui_refresh_state["finish_refreshed"] = True
        finally:
            root.after(100, poll_queues)

