    root.bind("<Return>", lambda _event: send_gui_input() if running["active"] else None)

    def refresh_scoreboard_preview(_event=None):
        if not running["active"]:
            set_scoreboard_teams(team_a_var.get(), team_b_var.get())
            scoreboard_status_var.set("Select a mode and teams, then start the sim.")

    mode_dropdown.bind("<<ComboboxSelected>>", lambda _event: set_team_dropdown_state())
    team_a_dropdown.bind("<<ComboboxSelected>>", refresh_scoreboard_preview)
    team_b_dropdown.bind("<<ComboboxSelected>>", refresh_scoreboard_preview)
    series_tabs.bind("<<NotebookTabChanged>>", lambda _event: update_extra_gui_tabs())
    set_team_dropdown_state()
    refresh_scoreboard_preview()
    clear_series_boxes()
    poll_queues()
    try:
        root.mainloop()
    except KeyboardInterrupt:
        # Ctrl+C from the launching terminal is a normal way to stop the GUI.
        # Close quietly instead of displaying a misleading traceback.
        try:
            root.destroy()
        except tk.TclError:
            pass

